QUESTIONS.push(
/* ---------------- ADEs: medication misadventures, definitions and the five types (pp. 4-9) ---------------- */
{id:"L22-001", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ade-types", skill:"figure", multi:true,
 concept:"ade-venn-overlap", tags:["smith"], source:"both",
 stem:"In the medication misadventures diagram, which of these can exist? Select all that apply.",
 options:[
  {t:"An ADR that is also a medication error", correct:true, why:"The ADR circle overlaps the medication error circle; Dr. Smith said ADRs can be medication errors."},
  {t:"A medication error that is an ADE but not an ADR", correct:true, why:"Part of the medication error circle lies inside the ADE circle but outside the ADR circle."},
  {t:"A medication error that causes no injury", correct:true, why:"Part of the medication error circle lies outside the ADE circle; an error counts regardless of patient outcome."},
  {t:"An ADR that is not an ADE", correct:false, why:"The ADR circle sits wholly inside the ADE circle: every ADR is an ADE."},
  {t:"An ADE outside medication misadventures", correct:false, why:"Medication misadventures is the outer oval that encloses all three terms."},
  {t:"An ADR that occurred at an overdose", correct:false, why:"An ADR is defined at doses normally used in humans, not at an overdose."}],
 teach:"Medication misadventures encloses adverse drug events (ADEs), medication errors and adverse drug reactions (ADRs). The ADR circle sits inside the ADE circle, so every ADR is an ADE. The medication error circle overlaps both: an error can be an ADR, an ADE that is not an ADR, or harmless.",
 quote:"ADRs can be medication errors, and they are considered an adverse drug event. You can have an adverse drug event that is a medication error, but is not causing an adverse drug reaction",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Medication Misadventures' (p. 4); transcript 10/28"},

{id:"L22-002", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ade-types", skill:"recall",
 concept:"ade-iom-definition", tags:["smith"], source:"both",
 stem:"How does the Institute of Medicine (IOM) define an adverse drug event (ADE)?",
 options:[
  {t:"Injury from a drug-related intervention, preventable or not", correct:true, why:"The two parts Dr. Smith pointed out: there is injury, and the cause may be preventable or non-preventable."},
  {t:"Any preventable event that may lead to inappropriate medication use or patient harm", correct:false, why:"That is the NCCMERP definition of a medication error; every medication error is preventable."},
  {t:"Any noxious, unintended effect of a drug at normal doses", correct:false, why:"That is the World Health Organization definition of an adverse drug reaction (ADR)."},
  {t:"An injury that a clinician could have prevented", correct:false, why:"The IOM definition includes non-preventable causes."}],
 teach:"The IOM defines an ADE as injury resulting from medical intervention related to a drug, from preventable or non-preventable causes. Two features matter: there is injury, and the cause may or may not be preventable. So an ADE can occur with the right drug given correctly.",
 quote:"the things that jump out to me are, these are a medication problem that causes injury. And sometimes they could be preventable and caught. Other times, they are not preventable",
 note:"The slide prints 'Institution of Medicine (IOM)'; Dr. Smith said 'Institute of Medicine'.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Adverse Drug Events (ADE) definition' (p. 5); transcript 10/28"},

{id:"L22-003", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ade-types", skill:"apply",
 concept:"ade-nonpreventable-example", tags:["smith","inclass"], source:"both",
 stem:"A patient receives the right drug at the right dose, given correctly, and is still injured. Which cause fits an ADE that is not preventable?",
 options:[
  {t:"A pharmacogenomic reaction", correct:true, why:"Pharmacogenomics: if the drug is not one we genotype for in practice, no provider is at fault and the event is not really preventable."},
  {t:"A wrong dose given by the nurse", correct:false, why:"That was her example of a preventable ADE."},
  {t:"A prescription filled with the wrong drug", correct:false, why:"A dispensing mistake is a preventable medication error."},
  {t:"A patient skipping doses at home", correct:false, why:"Nonadherence leads to therapeutic failure, a different ADE type."}],
 teach:"An ADE can occur even when the right drug is given correctly. Her example: a patient's genetic background gives an unwanted effect from a drug not normally genotyped for in practice. No provider is at fault.",
 quote:"Yeah, their pharmacogenomics could have an impact.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Adverse Drug Events (ADE) definition' (p. 5); transcript 10/28"},

{id:"L22-004", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ade-types", skill:"apply",
 concept:"ade-requires-injury", tags:["smith","inclass"], source:"transcript",
 stem:"An order is written for ten times the intended dose, but the pharmacist catches it and the patient never receives it. Is this an adverse drug event?",
 options:[
  {t:"No; an ADE requires an injury, though it is a medication error", correct:true, why:"No injury occurred, so it is a medication error but not an ADE."},
  {t:"Yes; any wrong-dose order is an ADE", correct:false, why:"A wrong-dose order with no injury is only a medication error."},
  {t:"Yes; it is an adverse drug reaction", correct:false, why:"No drug was given and no injury occurred, so there is no ADR."},
  {t:"No; a prescribing mistake like this is not even a medication error", correct:false, why:"A wrong-dose order is itself a medication error; it is simply not an ADE without injury."}],
 teach:"An ADE requires injury. A wrong-dose order that never harms anyone is a medication error but not an ADE. When the wrong dose is actually given and injures the patient, it is a preventable ADE.",
 quote:"well, no, that has the, has to have injury here for it to be an average drug event, right, but the wrong dose is given, yeah, mhm.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Adverse Drug Events (ADE) definition' (p. 5); transcript 10/28"},

{id:"L22-005", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ade-types", skill:"recall", multi:true,
 concept:"ade-five-types", tags:["smith"], source:"both",
 stem:"Which are among the five categories of ADEs? Select all that apply.",
 options:[
  {t:"Therapeutic failures", correct:true, why:"The first of the five types."},
  {t:"Adverse drug withdrawal events", correct:true, why:"The second of the five types."},
  {t:"Overdoses", correct:true, why:"The third of the five types."},
  {t:"Medication errors", correct:true, why:"The fourth type; ADRs are the fifth."},
  {t:"Medication misadventures", correct:false, why:"This is the umbrella term that encloses ADEs, medication errors and ADRs, not a type of ADE."},
  {t:"Drug interactions", correct:false, why:"A drug interaction is not one of the five ADE categories."},
  {t:"Pharmaceutical incompatibilities", correct:false, why:"A pharmaceutical incompatibility is not one of the five ADE categories."}],
 teach:"ADEs are classified into five categories: therapeutic failures, adverse drug withdrawal events, overdoses, medication errors and adverse drug reactions (ADRs). Medication misadventures is the umbrella term over ADEs, errors and ADRs, not a category.",
 quote:"They're classified into these 5 different categories usually, so therapeutic failure, uh, withdrawals, overdoses, med errors, and then ADRs, adverse drug reactions",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Types of ADEs' (p. 6); transcript 10/28"},

{id:"L22-006", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ade-types", skill:"recall",
 concept:"therapeutic-failure-cause", tags:["smith"], source:"both",
 stem:"A patient gets suboptimal amounts of a medication, and the condition fails to stabilize. What is the most common reason for this type of ADE?",
 options:[
  {t:"Patient nonadherence", correct:true, why:"Therapeutic failures are mostly seen with nonadherence: patients not taking their medications as they are supposed to."},
  {t:"A genetic variant", correct:false, why:"A variant can cause an ADE, but nonadherence is the biggest reason for therapeutic failure."},
  {t:"Abrupt stopping of a long-term drug", correct:false, why:"That causes an adverse drug withdrawal event."},
  {t:"Drug interactions in the gut", correct:false, why:"Not the reason Dr. Smith gave for therapeutic failure."}],
 teach:"A therapeutic failure is when suboptimal amounts of a medication are given and the condition fails to stabilize or symptoms worsen. The biggest reason is patient nonadherence. Pharmacists should check their counseling with teach-back.",
 quote:"a lot of times therapeutic failures are mostly seen as patient non-adherence. That's probably the biggest reason why we get therapeutic failures.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Therapeutic Failures' (p. 7); transcript 10/28"},

{id:"L22-007", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ade-types", skill:"apply",
 concept:"withdrawal-event-drugs", tags:["smith","inclass"], source:"both",
 stem:"Besides opioids and antihypertensives, which central nervous system (CNS) drug class can cause an adverse drug withdrawal event when stopped abruptly?",
 options:[
  {t:"SSRIs", correct:true, why:"She prompted for a CNS category and accepted SSRIs."},
  {t:"Over-the-counter iron supplements for anemia", correct:false, why:"Iron came up as a common accidental overdose in children."},
  {t:"Statins", correct:false, why:"Statins came up among the drugs causing most ADRs."},
  {t:"Radiocontrast dye", correct:false, why:"Radiocontrast came up as a pseudoallergic reaction."}],
 teach:"An adverse drug withdrawal event is a withdrawal syndrome after a patient on long-term therapy stops the drug, especially abruptly. Examples: opioids, hypertension medications and SSRIs.",
 quote:"Opioids Yeah, hypertension meds. I'm thinking of another category like in the CNS realm. Yeah, SSRI's",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Adverse Drug Withdrawal Events' (p. 8); transcript 10/28"},

{id:"L22-008", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ade-types", skill:"apply",
 concept:"overdose-geriatric", tags:["smith","inclass"], source:"both",
 stem:"An older patient takes two calcium channel blockers for several days in a row by mistake. What is this called, and why does it happen?",
 options:[
  {t:"A chronic overdose; the patient forgets doses taken", correct:true, why:"Geriatric patients sometimes forget; pill boxes help. The symptoms differ from an acute overdose."},
  {t:"An intentional overdose; common in older adults", correct:false, why:"She said intentional overdoses are rare in geriatric patients; young adults to adults are the ones doing them."},
  {t:"A therapeutic failure; too little drug reached the target", correct:false, why:"Here the patient got too much drug, not too little."},
  {t:"A withdrawal event; the patient stopped abruptly", correct:false, why:"The patient took extra drug; nothing was stopped."}],
 teach:"Accidental overdoses occur most often in pediatric and geriatric patients. Older patients may forget whether they took a dose; doubling up on cardiac drugs for days gives a chronic overdose, whose symptoms differ from an acute one. Intentional overdoses are rare in the elderly.",
 quote:"Our geriatric patients, they sometimes forget.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Drug Overdoses' (p. 9); transcript 10/28"},

{id:"L22-009", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ade-types", skill:"recall",
 concept:"overdose-pediatric-iron", tags:["smith","inclass"], source:"transcript",
 stem:"Which over-the-counter product is one of the most common accidental pediatric overdoses, partly because the tablets look like candy?",
 options:[
  {t:"Iron tablets", correct:true, why:"Coated, smooth, colorful tablets that look like candy."},
  {t:"Prescription opioids", correct:false, why:"Opioids came up for withdrawal and for ADRs, not as her pediatric example."},
  {t:"Calcium channel blockers", correct:false, why:"These came up for chronic overdose in older patients."},
  {t:"Antidepressants", correct:false, why:"Antidepressants came up among drugs known for ADRs."}],
 teach:"Children most often overdose on over-the-counter iron tablets, which are coated, smooth and colorful and look like candy. Medications are not always kept up high, and childproof caps cannot be counted on.",
 quote:"sometimes the most common meds that kids will overdose on are iron, over the counter iron tablets.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Drug Overdoses' (p. 9); transcript 10/28"},

/* ---------------- Medication errors (pp. 10-11) ---------------- */
{id:"L22-010", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"med-errors", skill:"recall",
 concept:"me-nccmerp-control", tags:["smith"], source:"both",
 stem:"The National Coordinating Council for Medication Error Reporting and Prevention (NCCMERP) defines a medication error as a preventable event that happens while the medication is in whose control?",
 options:[
  {t:"Healthcare professional, patient, or consumer", correct:true, why:"All three are in the definition; patients, and pharmacists, can be culpable."},
  {t:"The prescriber and the dispensing pharmacist", correct:false, why:"The definition is wider than these two roles."},
  {t:"Healthcare professionals, but not patients", correct:false, why:"Patients and consumers are included: a patient can take a drug wrongly at home."},
  {t:"The patient or consumer, but not professionals", correct:false, why:"Healthcare professionals are named too, not just patients."}],
 teach:"NCCMERP defines a medication error as any preventable event that may cause or lead to inappropriate medication use or patient harm while the medication is in the control of the healthcare professional, patient or consumer. Patients and pharmacists can be culpable.",
 quote:"while the medication is in the control of the healthcare professional, patient, or consumer.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Medication Errors (MEs)' (p. 10); transcript 10/28"},

{id:"L22-011", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"med-errors", skill:"tell",
 concept:"me-all-preventable", tags:["smith"], source:"both",
 stem:"Which statement about medication errors (MEs) is true?",
 options:[
  {t:"All MEs are preventable", correct:true, why:"Preventable is part of the NCCMERP definition: all MEs are preventable."},
  {t:"All MEs lead to serious consequences", correct:false, why:"Not all MEs lead to serious consequences."},
  {t:"An ME counts only when the patient is harmed", correct:false, why:"An ME involves any mistake in the medication process, regardless of patient outcome."},
  {t:"Some MEs are non-preventable", correct:false, why:"Non-preventable causes belong to the ADE definition, not to MEs."}],
 teach:"Every medication error is preventable; that is part of the NCCMERP definition. Not all lead to serious consequences, and an error counts regardless of patient outcome. When errors occur the whole process is evaluated.",
 quote:"Not all med errors lead to serious consequences, OK, but all medication errors are preventable.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Medication Errors (MEs)' (p. 10); transcript 10/28"},

{id:"L22-012", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"med-errors", skill:"apply",
 concept:"me-prevention-process", tags:["smith","inclass"], source:"transcript",
 stem:"In an inpatient pharmacy's stock area, how are drugs with similar-sounding names handled to prevent medication errors?",
 options:[
  {t:"They are stored apart from each other", correct:true, why:"Stock is often alphabetical, so look-alike names that start with the same letter are separated."},
  {t:"They are stored side by side for comparison", correct:false, why:"Side by side is what alphabetical storage would do; that is the risk being removed."},
  {t:"They are relabeled with the same color", correct:false, why:"Labeling is made distinct, as with high-concentration insulin, not alike."},
  {t:"They are removed from the formulary", correct:false, why:"She described separating them, not removing them."}],
 teach:"Process methods to prevent medication errors: clear documentation of orders, separate storage for drugs with similar-sounding names (alphabetical stock would put them side by side), and distinct labeling and storage for high-concentration insulin.",
 quote:"So we will often separate drugs that have similar sounding names, uh, especially if they start with the same letter.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Medication Errors (MEs)' (p. 10); transcript 10/28"},

{id:"L22-013", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"med-errors", skill:"apply",
 concept:"me-report-merp", tags:["smith"], source:"both",
 stem:"A pharmacist sees a dispensing process that is about to cause an error; no patient has been harmed yet. Where should a clinician report it?",
 options:[
  {t:"Medication Errors Reporting Program", correct:true, why:"Clinicians report medication errors to the Institute for Safe Medication Practices MERP, even when the error has not happened yet."},
  {t:"MedWatch", correct:false, why:"MedWatch is where ADRs are reported."},
  {t:"Nowhere, as long as no harm occurred", correct:false, why:"Dr. Smith said there is a duty to report even if the error does not happen."},
  {t:"Drug Safety Communications", correct:false, why:"That is how the FDA sends safety information out, not a reporting route."}],
 teach:"Clinicians report medication errors to the Institute for Safe Medication Practices (ISMP) Medication Errors Reporting Program (MERP), a confidential, voluntary program that analyzes the system causes of errors. There is a duty to report even an error that is only starting; first get it stopped.",
 quote:"We have a, a duty to, to do this reporting as healthcare providers, um, even if the error doesn't happen, and, but you see it starting, remember, it's the process too, so we need to report that.",
 note:"The slide calls MERP 'confidential, voluntary'; Dr. Smith called it anonymous. She also said 'Institute for Safe Medical Practices' for the slide's 'Institute for Safe Medication Practices'.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Reporting Medication Errors' (p. 11); transcript 10/28"},

/* ---------------- Adverse drug reactions: definition and reporting (p. 12) ---------------- */
{id:"L22-014", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"adr-def", skill:"tell",
 concept:"adr-who-correct-dose", tags:["smith"], source:"both",
 stem:"What feature of the World Health Organization (WHO) definition sets an adverse drug reaction (ADR) apart from the other ADE types?",
 options:[
  {t:"It occurs at the right dose", correct:true, why:"Doses used in humans for prophylaxis, diagnosis or therapy: not an overdose."},
  {t:"It is a preventable event", correct:false, why:"Being a preventable event describes a medication error, not an ADR."},
  {t:"It requires a dosing mistake", correct:false, why:"No mistake is needed; the drug is given at a normal dose."},
  {t:"It follows stopping the drug", correct:false, why:"That is an adverse drug withdrawal event."}],
 teach:"WHO defines an ADR as any noxious, unintended and undesired effect of a drug at doses used in humans for prophylaxis, diagnosis or therapy. What sets it apart is that the drug is at the right dose, not an overdose, and no mistake is needed.",
 quote:"In other words, it's, it's the drug at the right dose, it's not an overdose causing symptoms, it's a drug at the right dose, OK?",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Adverse Drug Reaction (ADR)' (p. 12); transcript 10/28"},

{id:"L22-015", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"adr-def", skill:"recall",
 concept:"adr-report-medwatch", tags:["smith"], source:"both",
 stem:"Through which program are ADRs reported?",
 options:[
  {t:"MedWatch", correct:true, why:"The FDA program for ADR reports; these reports feed postmarketing surveillance."},
  {t:"ISMP MERP", correct:false, why:"That program takes medication error reports."},
  {t:"Drug Safety Communications", correct:false, why:"That is how the FDA sends safety news out to clinicians."},
  {t:"NCCMERP", correct:false, why:"NCCMERP wrote the medication error definition."}],
 teach:"ADRs are reported through the FDA's MedWatch program. These reports feed postmarketing surveillance, the data that can show a drug needs a label change or removal from the market.",
 quote:"when we hear of an adverse drug reaction, we're reporting it to the MedWatch system.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Adverse Drug Reaction (ADR)' (p. 12); transcript 10/28"},

/* ---------------- Drug approval process and ADEs (pp. 14-16) ---------------- */
{id:"L22-016", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"drug-approval", skill:"apply",
 concept:"approval-why-pulled", tags:["smith","inclass"], source:"both",
 stem:"Why can a drug that passed a rigorous approval process be pulled from the market after launch?",
 options:[
  {t:"Far more people take it, so rare reactions appear", correct:true, why:"Trial populations are limited; on the market many more people use the drug and the rare, often very bad, reaction pops up."},
  {t:"Phase 1 trials enroll patients who have the disease", correct:false, why:"Phase 1 enrolls small numbers of healthy subjects."},
  {t:"Adverse events are not recorded in clinical trials", correct:false, why:"Trials record side effects; the problem is their size and scope."},
  {t:"The FDA approves without phase 3 data", correct:false, why:"Phase 3 is the larger patient study in the process she described."}],
 teach:"Trial populations are limited: phase 1 is small and healthy, phase 2 confirms the dose in patients, phase 3 is larger but still limited and often adults only. Once marketed, far more people take the drug, and a rare, often severe ADR can appear.",
 quote:"And so most of the time the drugs that we've pulled from the market after they've been launched have been pulled because we had enough people taking the drugs that the rare adverse reaction popped up.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Illustration of Drug Approval Process and ADEs' (p. 14); transcript 10/28"},

{id:"L22-017", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"drug-approval", skill:"recall",
 concept:"approval-pulled-liver", tags:["smith"], source:"transcript",
 stem:"Most of the time, which type of reaction prompts a drug to be pulled from the market after launch?",
 options:[
  {t:"Liver toxicity", correct:true, why:"Dr. Smith named liver toxicity as the most common reason."},
  {t:"Cancer after long-term use", correct:false, why:"A student raised delayed effects such as cancer; Dr. Smith named a different reaction as the most common reason."},
  {t:"Tinnitus", correct:false, why:"Tinnitus from aspirin was Dr. Smith's example of intolerance."},
  {t:"Dry mouth", correct:false, why:"Dry mouth is a predictable pharmacologic side effect."}],
 teach:"Rare reactions found after launch are often very bad ones, and most of the time the reaction that gets a launched drug pulled is liver toxicity.",
 quote:"Most of the time, the reaction that prompts us to pull drugs from the market once they've already launched our liver toxicity.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Illustration of Drug Approval Process and ADEs' (p. 14); transcript 10/28"},

{id:"L22-018", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"drug-approval", skill:"recall", multi:true,
 concept:"premarketing-limits", tags:["smith"], source:"both",
 stem:"Which are limitations of premarketing clinical trials? Select all that apply.",
 options:[
  {t:"Short duration", correct:true, why:"Effects after chronic use or with a long latency cannot be detected."},
  {t:"Small sample size", correct:true, why:"Usually fewer than 4,000 subjects, so effects rarer than 1/1,000 are hard to detect."},
  {t:"Narrowly defined populations", correct:true, why:"Children, women of childbearing age and the elderly are generally not included."},
  {t:"Limited comparison groups", correct:true, why:"The comparison group is often only placebo."},
  {t:"Heavy enrollment of elderly patients", correct:false, why:"The elderly are generally left out; that is the narrow-population problem."},
  {t:"A standard-of-care comparator in every trial", correct:false, why:"Comparison groups are limited and often only placebo, not a standard-of-care arm."}],
 teach:"Premarketing trials are short, so effects of chronic use or long latency are missed; small (usually under 4,000 subjects, so effects rarer than 1 in 1,000 are hard to detect); limited to narrow populations without children, pregnant women or the elderly; and often compared only to placebo.",
 quote:"oftentimes they're relatively short duration studies. We've already mentioned small sample size. I already mentioned narrowly defined populations.",
 note:"The 4,000-subject and 1/1,000 figures are on the slide; Dr. Smith pointed to that column without reading them. For the narrow set of indications she spoke of narrow patient outcomes in phase 3 rather than the slide's wording about manufacturers pursuing specific indications.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Limitations to premarketing clinical trials' (p. 15); transcript 10/28"},

{id:"L22-019", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"drug-approval", skill:"recall",
 concept:"fda-guidelines-not-law", tags:["smith"], source:"both",
 stem:"The FDA has issued guidelines on including geriatric and pediatric patients in clinical trials. What force do these guidelines carry?",
 options:[
  {t:"Suggestions, sometimes with incentives", correct:true, why:"The FDA cannot make a company do this; the guidelines are recommendations, sometimes with incentives attached."},
  {t:"Binding federal law for trial sponsors", correct:false, why:"FDA guidelines are not law."},
  {t:"A condition of every drug approval", correct:false, why:"They are recommendations, not approval requirements."},
  {t:"Rules for generic drugs only", correct:false, why:"They address efficacy, safety, pharmacokinetic and pharmacodynamic data in special populations."}],
 teach:"The FDA issued guidelines on including geriatric patients in phase II and III studies, and guidelines with incentives for pediatric and geriatric data. The FDA cannot make a company do this: the guidelines are not law, so they are suggestions.",
 quote:"They write these guidelines, so they're not law, but they're suggestions",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Improving the Drug Approval Process regarding ADEs' (p. 16); transcript 10/28"},

{id:"L22-020", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"drug-approval", skill:"recall",
 concept:"approval-add-pgx", tags:["smith"], source:"transcript",
 stem:"Besides geriatric and pediatric enrollment, what is now encouraged in clinical trials to improve the drug approval process regarding ADEs?",
 options:[
  {t:"Pharmacogenomics (PGx)", correct:true, why:"Companies are encouraged to look at what a genetic variant does to patient response, with separate FDA guidance."},
  {t:"Longer animal studies", correct:false, why:"Delayed effects in short animal studies came up only as a student answer about why drugs are pulled from the market."},
  {t:"Placebo-only comparison groups", correct:false, why:"Placebo-only comparison is listed as a limitation."},
  {t:"Removing children from trials", correct:false, why:"The move is toward including pediatric patients under careful guidelines."}],
 teach:"Besides adding pediatric patients to the geriatric bullet, she added pharmacogenomics (PGx). A company that believes PGx should be considered is highly encouraged to look at what a genetic variant does to patient response in its trials; the FDA has separate guidance for that.",
 quote:"So, let's add, besides PG or PEDs, let's add PGX.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Improving the Drug Approval Process regarding ADEs' (p. 16); transcript 10/28"},

/* ---------------- Postmarketing surveillance and FDA communications (pp. 17-18) ---------------- */
{id:"L22-021", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"postmarketing", skill:"recall", multi:true,
 concept:"pms-functions", tags:["smith"], source:"both",
 stem:"Which are functions of the FDA's Post Marketing Surveillance (PMS) program? Select all that apply.",
 options:[
  {t:"Monitoring approved drug use", correct:true, why:"The first function listed."},
  {t:"Monitoring serious ADRs of approved drugs", correct:true, why:"PMS should catch serious ADRs missed in trials."},
  {t:"Starting epidemiologic studies", correct:true, why:"These estimate risk or test specific hypotheses about who is at risk."},
  {t:"Changing the labeling or package insert", correct:true, why:"One of the primary uses, along with pulling the drug from the market."},
  {t:"Setting the dose in phase 2 trials", correct:false, why:"Dose finding happens before approval; PMS starts after launch."},
  {t:"Approving the drug for marketing", correct:false, why:"Approval precedes launch; PMS begins after the drug is on the market."}],
 teach:"PMS monitors approved drug use and serious ADRs missed in trials, and its data launch large, hypothesis-driven epidemiologic studies. A primary use is to modify the labeling or pull the drug; with good data a label change can sometimes suffice.",
 quote:"Sometimes we can handle that post-marketing surveillance adverse response that's popping up by changing the labeling, OK, if you get really good data from your Epi studies, OK?",
 cite:"ADE-Lecture-Students-2026.pdf slides 'Illustration of Drug Approval Process and ADEs' (p. 14), 'Drug Approval Process Post Marketing Surveillance' (p. 17); transcript 10/28"},

{id:"L22-022", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"postmarketing", skill:"apply",
 concept:"fda-drug-safety-communications", tags:["smith"], source:"both",
 stem:"A pharmacist wants to learn promptly about label changes, market withdrawals and drug shortages. Where should a pharmacist look, and how often?",
 options:[
  {t:"The FDA Drug Safety Communications page, weekly", correct:true, why:"The FDA now puts this information on one website; she suggested checking once or twice a week."},
  {t:"Paper recall notices mailed to the pharmacy, as they arrive", correct:false, why:"That was the older, fragmented method that the website replaced."},
  {t:"The MedWatch reporting form, monthly", correct:false, why:"MedWatch is for reporting ADRs to the FDA."},
  {t:"The package insert, at each refill", correct:false, why:"A clinician who does not know the label changed would not know to look."}],
 teach:"After PMS leads to a label change or withdrawal, every provider has to find out, or the problem continues. The FDA now puts its Drug Safety Communications on one website, which also covers shortages and recalls. She suggested checking it once or twice a week.",
 quote:"They've changed in the last 5 years their methods of reaching out to us, and they now tend to put that kind of information on this FDA website.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Drug Approval Process and ADEs Communications' (p. 18); transcript 10/28"},

/* ---------------- ADR scope of the problem and institutional surveillance (pp. 20, 22) ---------------- */
{id:"L22-023", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"adr-scope", skill:"apply",
 concept:"adr-polypharmacy-probability", tags:["smith"], source:"both",
 stem:"A hospitalized patient is receiving 17 drugs. What is the probability of an ADR?",
 options:[
  {t:"Over 40%", correct:true, why:"More than 15 drugs in a hospitalized patient: ADR probability above 40%."},
  {t:"About 5%", correct:false, why:"That is for fewer than 6 drugs in a hospitalized patient."},
  {t:"About 20%", correct:false, why:"That is the estimate for ambulatory patients."},
  {t:"About 90%", correct:false, why:"90% is the share of ADRs caused by a number of widely used drugs."}],
 teach:"The more drugs given, the more likely an ADR. Hospitalized patients on fewer than 6 drugs have about a 5% probability; on more than 15 drugs it is above 40%. Ambulatory patients are about 20%.",
 quote:"but if a hospitalized patient's on greater than 15 drugs, that ADR probability goes up to more than 40%",
 cite:"ADE-Lecture-Students-2026.pdf slide 'ADR Scope of Problem' (p. 20); transcript 10/28"},

{id:"L22-024", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"adr-scope", skill:"recall", multi:true,
 concept:"adr-widely-used-drugs", tags:["smith","inclass"], source:"both",
 stem:"A handful of widely used drugs cause about 90% of ADRs. Which drug groups are among them? Select all that apply.",
 options:[
  {t:"Opioids", correct:true, why:"On her list."},
  {t:"Cardiac medications such as statins", correct:true, why:"A student named statins; she placed them with cardiac meds."},
  {t:"Diabetes medications", correct:true, why:"On her list; with opioids and cardiac meds, the big three."},
  {t:"Antidepressants", correct:true, why:"She added antidepressants from the CNS realm."},
  {t:"Topical antihistamines", correct:false, why:"Not named; contact dermatitis from a topical antihistamine is only a table example of type IV reactions."},
  {t:"Beta-lactam antibiotics", correct:false, why:"Not among the groups she named as causing most ADRs."},
  {t:"Proton pump inhibitors", correct:false, why:"Not among the groups she named as causing most ADRs."}],
 teach:"A handful of widely used drugs cause about 90% of ADRs. Her list: opioids, cardiac medications (statins included) and diabetes medications as the big three, plus antidepressants.",
 quote:"I, I put on the list opioids now, especially cardiac meds, diabetic medications.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'ADR Scope of Problem' (p. 20); transcript 10/28"},

{id:"L22-025", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"adr-scope", skill:"recall",
 concept:"adr-sentinel-event", tags:["smith"], source:"both",
 stem:"In ADR surveillance at institutions compliant with the hospital accrediting body (JCAHO), what is a sentinel event, and what may it trigger?",
 options:[
  {t:"Risk of death or serious injury; a JCAHO visit", correct:true, why:"Risk of death or serious physical or psychological injury; it may trigger an unscheduled JCAHO visit and process reviews."},
  {t:"An ADR reported to MedWatch; a label change", correct:false, why:"A sentinel event is defined by severity, not by reporting."},
  {t:"A medication error with no harm; staff retraining", correct:false, why:"A sentinel event involves death or serious injury."},
  {t:"A predictable side effect; a dose change", correct:false, why:"Predictable side effects are not what defines a sentinel event."}],
 teach:"Accrediting bodies make ADR surveillance a compliance requirement: institutions define significant ADRs, assess them and follow up on their causes. A sentinel event carries a risk of death or serious injury and may trigger an unscheduled JCAHO visit.",
 quote:"So a sentinel event would be the ADR is so bad that death could death occurred or a serious physical or psychological injury happened.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Surveillance and Management of ADRs' (p. 22); transcript 10/28"},

/* ---------------- Causality and the Naranjo algorithm (p. 21 and the one-page Naranjo Algorithm) ---------------- */
{id:"L22-026", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"naranjo", skill:"recall", readingId:"naranjo",
 concept:"naranjo-purpose", tags:["smith"], source:"both",
 stem:"A patient develops a new symptom while on several drugs. What does the Naranjo algorithm help the clinician decide?",
 options:[
  {t:"Whether a drug caused it", correct:true, why:"It ranks the causality of an ADR, separating a drug cause from a new or changed disease state."},
  {t:"Which genotype test to order", correct:false, why:"Genotype-guided decisions come from pharmacogenomic guidelines."},
  {t:"How to report it to the FDA", correct:false, why:"Reporting is through MedWatch; Naranjo assesses causality."},
  {t:"Which hypersensitivity type it is", correct:false, why:"The Gell and Coombs table classifies hypersensitivity; Naranjo addresses causality."}],
 teach:"A new symptom may be a new disease, a change in the patient, a new drug, or a long-used drug the changed patient now reacts to. The Naranjo algorithm, worked through with the patient and the literature, scores how likely the drug is the cause. It depends heavily on timing.",
 quote:"Maybe it's another disease state coming on for them. Uh, maybe it's a disease state that's changed, or it could be a drug. And so this exercise will help you delineate between that, OK?",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Causality of Adverse Drug Reactions' (p. 21); Naranjo Algorithm (one page); transcript 10/28"},

{id:"L22-027", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"naranjo", skill:"tell", readingId:"naranjo",
 concept:"naranjo-rankings", tags:["smith"], source:"both",
 stem:"Among the Naranjo causality rankings, which one means the drug appears to be associated with the reaction?",
 options:[
  {t:"Possible", correct:true, why:"Possible: drug appears to be associated."},
  {t:"Probable", correct:false, why:"Probable: drug is the apparent cause."},
  {t:"Definite", correct:false, why:"Definite: drug is likely the true cause."},
  {t:"Remote", correct:false, why:"Remote: drug is not likely responsible."}],
 teach:"The rankings: definite (drug is likely the true cause), probable (apparent cause), possible (appears associated) and remote (not likely responsible). The page prints the score bands: 9 definite, 5-8 probable, 1-4 possible, 0 doubtful.",
 quote:"So these are the rankings definite, probable, possible, or remote.",
 note:"Conflict: the deck slide (p. 21) and Dr. Smith's words name the lowest ranking 'remote'; the Naranjo Algorithm page names a score of 0 'doubtful'. Keyed to the slide and her words; 'doubtful' is not offered as an option.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Causality of Adverse Drug Reactions' (p. 21); Naranjo Algorithm (one page); transcript 10/28"},

{id:"L22-028", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"naranjo", skill:"calc", readingId:"naranjo",
 concept:"naranjo-scoring", tags:["smith"], source:"both",
 stem:"Naranjo scoring: there are previous conclusive reports of the reaction; the reaction appeared after the drug was started; it improved when the drug was stopped; the drug was never re-given, so question 4 is answered 'do not know'; no alternative cause could explain it; every other question is answered 'do not know'. What is the total and its category?",
 options:[
  {t:"6; probable", correct:true, why:"+1 (reports) +2 (appeared after) +1 (improved) +0 (not re-given) +2 (no alternative cause) = 6, in the 5-8 probable band."},
  {t:"4; possible", correct:false, why:"Scores 'no' on alternative causes as 0; a 'no' there earns +2."},
  {t:"9; definite", correct:false, why:"Too high: questions answered 'do not know' score 0."},
  {t:"2; possible", correct:false, why:"Misses the +2 for the reaction appearing after the drug and the +2 for no alternative cause."}],
 teach:"Each of the 10 questions is answered yes, no or do not know, and the points differ by question: a yes can be +2 or +1, some answers are negative, and do not know is always 0. Here: reports +1, appeared after +2, improved on stopping +1, not re-given 0, no alternative cause +2. Total 6, probable (5-8).",
 quote:"Pay attention to the fact that, uh, sometimes a yes is 2 points, sometimes it's 1 point, sometimes a no is negative.",
 cite:"Naranjo Algorithm (one page), questions 1-10 and total score; ADE-Lecture-Students-2026.pdf slide 'Causality of Adverse Drug Reactions' (p. 21); transcript 10/28"},

{id:"L22-029", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"naranjo", skill:"recall", readingId:"naranjo", multi:true,
 concept:"naranjo-temporal-questions", tags:["smith","inclass"], source:"both",
 stem:"Which Naranjo questions are about timing? Select all that apply.",
 options:[
  {t:"Did the adverse event appear after the suspected drug was given?", correct:true, why:"Question 2; she named it first."},
  {t:"Did the reaction improve when the drug was discontinued?", correct:true, why:"Question 3, which includes giving a specific antagonist."},
  {t:"Did the reaction reappear when a placebo was given?", correct:true, why:"Question 6; she said she considers it a time kind of thing."},
  {t:"Are there previous conclusive reports on this reaction?", correct:false, why:"Question 1 calls for a literature search, not timing."},
  {t:"Was the drug detected in blood at toxic concentrations?", correct:false, why:"Question 7 is about a measured level, not timing."},
  {t:"Did the patient have a similar reaction to the same or similar drug before?", correct:false, why:"Question 9 is about history, not timing."}],
 teach:"A large part of the Naranjo algorithm is timing between drug exposure and response. She named question 2 (appeared after the drug), question 3 (improved on stopping), question 4 (reappeared on re-administration) and question 6 (placebo) as time related. Question 1 needs a literature search.",
 quote:"Also, I, I consider like 6 to be a time kind of thing.",
 cite:"Naranjo Algorithm (one page), questions 1-10; ADE-Lecture-Students-2026.pdf slide 'Causality of Adverse Drug Reactions' (p. 21); transcript 10/28"},

{id:"L22-030", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"naranjo", skill:"calc", readingId:"naranjo",
 concept:"naranjo-q5-alternative", tags:["smith"], source:"both",
 stem:"On the Naranjo algorithm, the patient has another drug that could on its own have caused the reaction. How does the answer to question 5 score?",
 options:[
  {t:"-1", correct:true, why:"Question 5: yes = -1, no = +2, do not know = 0."},
  {t:"+2", correct:false, why:"+2 is for 'no': no alternative cause."},
  {t:"+1", correct:false, why:"+1 is not a choice on question 5."},
  {t:"0", correct:false, why:"0 is for 'do not know'."}],
 teach:"Question 5 asks whether alternative causes or drugs could on their own have caused the reaction. A yes points away from the drug and lowers the score (-1); a no raises it (+2); do not know is 0. The point values vary by question.",
 quote:"So make sure that you are scoring the responses appropriately with this algorithm",
 cite:"Naranjo Algorithm (one page), question 5; ADE-Lecture-Students-2026.pdf slide 'Causality of Adverse Drug Reactions' (p. 21); transcript 10/28"},

{id:"L22-031", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"naranjo", skill:"apply", readingId:"naranjo",
 concept:"naranjo-literature", tags:["smith"], source:"both",
 stem:"To answer Naranjo question 1, 'Are there previous conclusive reports on this reaction?', what does the clinician need to do?",
 options:[
  {t:"Search the published literature", correct:true, why:"Dr. Smith said to do due diligence with a dive into the literature."},
  {t:"Re-administer the drug to the patient", correct:false, why:"That answers question 4, on rechallenge."},
  {t:"Measure the drug level in blood", correct:false, why:"That answers question 7, on toxic concentrations."},
  {t:"Give the patient a placebo", correct:false, why:"That answers question 6."}],
 teach:"Some Naranjo questions are answered by talking with the patient about timing; question 1 instead requires a literature search for published reports that back the suspicion. A yes scores +1.",
 quote:"So you need to do your due diligence and confirm your suspicions by doing a dive into the literature to answer some of these questions as well, OK.",
 cite:"Naranjo Algorithm (one page), question 1; ADE-Lecture-Students-2026.pdf slide 'Causality of Adverse Drug Reactions' (p. 21); transcript 10/28"},

/* ---------------- Immunologic and nonimmunologic reactions (p. 23) ---------------- */
{id:"L22-032", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"immuno-nonimmuno", skill:"tell",
 concept:"immuno-vs-nonimmuno-predictable", tags:["smith"], source:"both",
 stem:"ADRs are grouped into two big buckets, immunologic and nonimmunologic. How do the two compare in predictability?",
 options:[
  {t:"Nonimmunologic often predictable; immunologic often not", correct:true, why:"Dr. Smith's contrast; some nonimmunologic reactions are still unpredictable."},
  {t:"Immunologic often predictable; nonimmunologic often not", correct:false, why:"Reversed."},
  {t:"Both buckets are predictable from the dose given", correct:false, why:"Immunologic reactions are often not predictable."},
  {t:"Neither bucket can be predicted from the drug", correct:false, why:"Nonimmunologic reactions such as pharmacologic side effects and drug toxicity are predictable."}],
 teach:"ADRs are immunologic or nonimmunologic. Nonimmunologic reactions are often predictable (side effects, toxicity, interactions, overdose); immunologic reactions are often not. Some nonimmunologic reactions are also unpredictable: pseudoallergic, idiosyncratic and intolerance.",
 quote:"things like the non-immunological reactions are predictable, where oftentimes the immunological reactions are not predictable, OK?",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Immunologic reactions' (p. 23; Riedl and Casillas 2003 table); transcript 10/28"},

{id:"L22-033", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"immuno-nonimmuno", skill:"tell",
 concept:"intolerance-aspirin-tinnitus", tags:["smith"], source:"both",
 stem:"Tinnitus after a single, small dose of aspirin is the classic example of which reaction type?",
 options:[
  {t:"Intolerance", correct:true, why:"An unpredictable nonimmunologic reaction; Dr. Smith called this the classic example."},
  {t:"Idiosyncratic reaction", correct:false, why:"The table's idiosyncratic example is hemolytic anemia in G6PD deficiency after primaquine."},
  {t:"Pseudoallergic reaction", correct:false, why:"Dr. Smith's pseudoallergic example was itching after radiocontrast dye."},
  {t:"Type I hypersensitivity", correct:false, why:"No immune mechanism is involved in intolerance."}],
 teach:"Intolerance is an unpredictable, nonimmunologic reaction to a small dose; tinnitus after one small aspirin dose is the classic example. The other unpredictable nonimmunologic reactions are pseudoallergic (the itch from radiocontrast dye, not a true allergy) and idiosyncratic.",
 quote:"um, things like tinnitus in the ear, um, after just one small dose of aspirin, that's a classic example of an intolerance.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Immunologic reactions' (p. 23; Riedl and Casillas 2003 table); transcript 10/28"},

{id:"L22-034", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"immuno-nonimmuno", skill:"tell", multi:true,
 concept:"nonimmuno-unpredictable", tags:["smith"], source:"both",
 stem:"Which nonimmunologic reactions are classed as unpredictable? Select all that apply.",
 options:[
  {t:"Pseudoallergic, such as itching from radiocontrast dye", correct:true, why:"It looks allergic but is the drug doing it; often unpredictable."},
  {t:"Idiosyncratic", correct:true, why:"Unpredictable by name, Dr. Smith said."},
  {t:"Intolerance", correct:true, why:"Tinnitus after a small aspirin dose; often unpredictable."},
  {t:"Pharmacologic side effect, such as dry mouth from antihistamines", correct:false, why:"Listed under predictable nonimmunologic reactions."},
  {t:"Drug-drug interaction", correct:false, why:"Listed under predictable nonimmunologic reactions."},
  {t:"Secondary effect, such as antibiotic-associated diarrhea", correct:false, why:"A secondary effect is a predictable nonimmunologic reaction."}],
 teach:"Nonimmunologic reactions split into predictable ones (pharmacologic side effect, secondary side effect, drug toxicity, drug-drug interactions, overdose) and unpredictable ones (pseudoallergic, idiosyncratic, intolerance). Be able to tell the two groups apart.",
 quote:"Sometimes it makes you itchy. People think that that's an allergic reaction. It's not, it's just the drug doing it.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Immunologic reactions' (p. 23; Riedl and Casillas 2003 table); transcript 10/28"},

/* ---------------- Predisposing and risk factors (pp. 24-25) ---------------- */
{id:"L22-035", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"risk-factors", skill:"tell",
 concept:"risk-immune-only", tags:["smith"], source:"both",
 stem:"In the table of patient risk factors for ADRs, which factor is listed only for hypersensitivity (immune) reactions?",
 options:[
  {t:"Asthma", correct:true, why:"Listed under hypersensitivity reactions, with use of beta blockers."},
  {t:"Renal insufficiency", correct:false, why:"Listed only for general (nonimmune) reactions."},
  {t:"Liver disease", correct:false, why:"Listed only for general (nonimmune) reactions."},
  {t:"Female gender", correct:false, why:"Listed in both columns."}],
 teach:"Nonimmune risk factors: female gender, serious illness, renal insufficiency, liver disease, polypharmacy, HIV infection, herpes infection, alcoholism, lupus. Immune (hypersensitivity) risk factors: female gender, adult, HIV infection, viral infection, previous hypersensitivity to a related drug, asthma (with beta blockers), genetic polymorphisms, lupus.",
 quote:"Categorizing the risk based on whether the reaction is non-immunologically based or immunologically based, OK?",
 cite:"ADE-Lecture-Students-2026.pdf slides 'Predisposing Factors to Adverse Drug Reactions' (p. 24), 'Risk Factors' (p. 25; Riedl and Casillas 2003 Table 4); transcript 10/28"},

/* ---------------- Hypersensitivity reactions (pp. 26-27, 33) ---------------- */
{id:"L22-036", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"hypersens", skill:"recall",
 concept:"hypersens-term-four-types", tags:["smith"], source:"both",
 stem:"A layperson calls it a 'drug allergy'. What term is used instead, and how many types are there?",
 options:[
  {t:"Hypersensitivity; four types", correct:true, why:"Types I, II, III and IV."},
  {t:"Idiosyncratic reaction; two types", correct:false, why:"Idiosyncratic reactions are nonimmunologic and may be mistaken for hypersensitivity."},
  {t:"Autoimmune reaction; four types", correct:false, why:"Autoimmune responses are a separate way drugs can activate the immune system."},
  {t:"Pseudoallergic reaction; three types", correct:false, why:"Pseudoallergic reactions are nonimmunologic."}],
 teach:"Drugs may activate the immune system, producing true drug allergies or sometimes autoimmune responses. What the layperson calls a drug allergy is a hypersensitivity reaction. There are four types (I, II, III, IV), and more than one can occur at once.",
 quote:"So the drug allergies are what the layperson might call it, but we're going to call those hypersensitivity reactions, and I want you to remember that there are 4 types of hypersensitivity reactions.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Hypersensitivity Drug Reactions' (p. 26); transcript 10/28"},

{id:"L22-037", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"hypersens", skill:"apply",
 concept:"hypersens-type1-timing", tags:["smith"], source:"both",
 stem:"Within an hour of a beta-lactam antibiotic dose, a patient develops urticaria and bronchospasm. Which hypersensitivity type fits?",
 options:[
  {t:"Type I", correct:true, why:"IgE-mediated; drug-IgE complexes on mast cells release histamine within minutes to hours."},
  {t:"Type II", correct:false, why:"Cytotoxic IgG or IgM against drug-coated cells; hemolytic anemia and other cytopenias, variable timing."},
  {t:"Type III", correct:false, why:"Immune complex; serum sickness 1 to 3 weeks after exposure."},
  {t:"Type IV", correct:false, why:"Delayed, cell-mediated; 2 to 7 days after cutaneous exposure."}],
 teach:"Timing is a real key to the type. Type I is IgE (immunoglobulin E) mediated: the drug-IgE complex binds mast cells, which release histamine, so urticaria, angioedema, bronchospasm or anaphylaxis appear within minutes to hours. Anaphylaxis from a beta-lactam is the example.",
 quote:"So, IgE mediated is usually within minutes to hours of an exposure, OK?",
 cite:"ADE-Lecture-Students-2026.pdf slides 'Immunologic reactions' (p. 23), 'Classification of hypersensitivity reactions' (p. 27; Gell and Coombs, Riedl and Casillas 2003 Table 2); transcript 10/28"},

{id:"L22-038", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"hypersens", skill:"apply",
 concept:"hypersens-type4-delayed", tags:["smith"], source:"both",
 stem:"Allergic contact dermatitis appears four days after a patient starts a topical antihistamine. Which hypersensitivity type fits?",
 options:[
  {t:"Type IV", correct:true, why:"Delayed, cell-mediated: MHC presentation of the drug to T cells, 2 to 7 days after cutaneous exposure."},
  {t:"Type I", correct:false, why:"IgE-mediated reactions appear within minutes to hours."},
  {t:"Type II", correct:false, why:"Cytotoxic antibodies give hemolytic anemia, neutropenia or thrombocytopenia."},
  {t:"Type III", correct:false, why:"Immune complex disease gives serum sickness, 1 to 3 weeks after exposure."}],
 teach:"Type IV is delayed and cell-mediated: drug molecules are presented to T cells by major histocompatibility complex (MHC) molecules, which release cytokines. It appears 2 to 7 days after cutaneous exposure as contact dermatitis or a maculopapular rash.",
 quote:"Type 4 which is delayed and it's cell-mediated rather than IgE mediated, that can happen days after a drug react or after a drug exposure.",
 cite:"ADE-Lecture-Students-2026.pdf slides 'Immunologic reactions' (p. 23), 'Classification of hypersensitivity reactions' (p. 27; Gell and Coombs, Riedl and Casillas 2003 Table 2); transcript 10/28"},

{id:"L22-039", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"hypersens", skill:"tell",
 concept:"hypersens-type3-serum-sickness", tags:["smith"], source:"both",
 stem:"Two weeks after a drug is started, a patient has serum sickness with fever, arthralgias and lymphadenopathy. Which hypersensitivity type fits?",
 options:[
  {t:"Type III", correct:true, why:"Immune complex: drug-antibody complexes deposit in tissue with complement activation, 1 to 3 weeks after exposure."},
  {t:"Type I", correct:false, why:"IgE-mediated reactions appear within minutes to hours."},
  {t:"Type II", correct:false, why:"Cytotoxic reactions give hemolytic anemia, neutropenia or thrombocytopenia."},
  {t:"Type IV", correct:false, why:"Delayed cell-mediated reactions give contact dermatitis or maculopapular rash, 2 to 7 days after cutaneous exposure."}],
 teach:"Type III (immune complex) reactions come from drug-antibody complexes depositing in tissue, with complement activation and inflammation, 1 to 3 weeks after exposure: serum sickness, fever, rash, arthralgias, lymphadenopathy, glomerulonephritis or vasculitis.",
 quote:"I do want you to remember these because these are important when we talk with our patients.",
 note:"Dr. Smith spoke only to type I and type IV timing; the type II and III rows are from the table she asked the class to remember.",
 cite:"ADE-Lecture-Students-2026.pdf slides 'Immunologic reactions' (p. 23), 'Classification of hypersensitivity reactions' (p. 27; Gell and Coombs, Riedl and Casillas 2003 Table 2); transcript 10/28"},

{id:"L22-040", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"hypersens", skill:"apply",
 concept:"hypersens-treatment", tags:["smith","inclass"], source:"transcript",
 stem:"Is a type I (IgE-mediated) hypersensitivity reaction treated differently from a type III or type IV reaction?",
 options:[
  {t:"Yes: antihistamines, then steroids for type I", correct:true, why:"Antihistamines are the biggest bet for type I, then steroids; steroids for sure for the other types."},
  {t:"No: all four types are treated the same way", correct:false, why:"She said what you do to help the patient will be different."},
  {t:"Yes: steroids for type I; antihistamines for others", correct:false, why:"Reversed: antihistamines lead for type I; steroids for the others."},
  {t:"Yes: no treatment for type IV", correct:false, why:"Steroids for sure for the other types, possibly with more therapy."}],
 teach:"Knowing the type changes treatment. For an IgE-mediated type I reaction, antihistamines are the biggest bet, then steroids. For the other types, steroids for sure.",
 quote:"You know, probably your biggest bet would be antihistamines, right? And then steroids, OK. For your other kinds of reactions, steroids for sure.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Classification of hypersensitivity reactions' (p. 27); transcript 10/28"},

{id:"L22-041", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"hypersens", skill:"recall", dupOf:"L21-055",
 concept:"sjs-carbamazepine-hla", tags:["smith","inclass"], source:"both",
 stem:"A patient with HLA-B*15:02 develops Stevens-Johnson syndrome. Which drug is the classic cause?",
 options:[
  {t:"Carbamazepine", correct:true, why:"The drug she named: carriers of its HLA-B risk variant are at high risk of Stevens-Johnson syndrome."},
  {t:"Trastuzumab", correct:false, why:"Trastuzumab was discussed for HER2 testing, not an HLA-B variant."},
  {t:"Warfarin", correct:false, why:"Warfarin was discussed for dosing genes, not an HLA-B variant."},
  {t:"Mercaptopurine", correct:false, why:"Mercaptopurine was discussed with TPMT, not an HLA-B variant."}],
 teach:"Stevens-Johnson syndrome is a painful and dangerous reaction that can involve the mouth and mucosal tract, not just the skin, and the skin can come off. Carbamazepine carries this risk in people with its HLA-B risk variant. Abacavir labeling now describes an all-organ hypersensitivity.",
 quote:"which drug did we talk about that, uh, people with a certain genetic variant of the HLAB gene were really at risk for having this kind of reaction? Yeah, carbamazepine",
 note:"Shown after the break from the deck slide titled 'Steven Johnson Syndrome' (p. 33), after a brief look at the list of skin reactions (p. 30) and an image of hives; the rest of the skin, liver and renal slides were skipped. Same fact as L21-055 (10/27). The handwritten 'abacavir' on the posted slide is a student's note and is not used.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Steven Johnson Syndrome' (p. 33); transcript 10/28"},

// L22 part 2 — Day 22 (10/28): Drug interactions (Dr. Smith). Exam 4.
// Sources, in her order of authority: the 10/28 Echo transcript (SPEAKER 0 is Dr. Smith; auto-captions, slips kept; a garbled
// caption is paraphrased, never quoted), then the deck "DDI Lecture Students 2026 (1).pdf" (cited by slide title and PDF page;
// handwriting on the posted copy, e.g. on pp. 9 and 15, is a student's and is not used). Taught pp. 2-30; p. 31 (Clinical
// Significance) was left to read on their own. Questions she put to the room are tagged "inclass".
/* ---------------- Introduction: definitions and classification (pp. 2-7) ---------------- */
{id:"L22-042", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-intro", skill:"recall",
 concept:"ddi-not-only-drug-drug", tags:["smith"], source:"both",
 stem:"Dr. Smith titled the topic \"drug interactions\" rather than \"drug-drug interactions\". What was her reason?",
 options:[
  {t:"The precipitant can be a food, herb or habit", correct:true, why:"She said interactions can be drugs with food, with herbal products or with habits such as smoking and drinking."},
  {t:"A second drug is the precipitant by definition", correct:false, why:"An interaction needs the object drug plus a second substance; the second substance just need not be a drug."},
  {t:"Interactions outside the body are the main concern", correct:false, why:"She set aside incompatibilities outside the body as a pharmaceutics topic and focused on interactions in the body."},
  {t:"The term \"drug-drug\" is reserved for beneficial pairs", correct:false, why:"She used \"drug-drug\" for beneficial pairs such as probenecid with penicillin too; that was not her reason."}],
 teach:"A drug interaction is an adverse response produced when a drug is given with another substance that modifies the patient's response. That substance can be a drug, a food, an herbal product or a habit such as smoking or drinking, so she says drug interactions, not drug-drug interactions.",
 quote:"The reason I don't say drug-drug is sometimes drug interactions are not just driven by drugs and drugs, it could be drugs and food, drugs and herbal products, drugs and other habits that we have.",
 cite:"DDI Lecture Students 2026 (1).pdf slides 'Outline' (p. 2) and 'Drug Interactions Introduction' (p. 5); (T) 10/28 transcript"},

{id:"L22-043", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-intro", skill:"tell",
 concept:"precipitant-vs-object", tags:["smith"], source:"both",
 stem:"In a drug interaction, which term names the drug, chemical or food that causes the interaction?",
 options:[
  {t:"The precipitant drug", correct:true, why:"The precipitant causes the interaction; Dr. Smith called it the bad guy."},
  {t:"The object drug", correct:false, why:"The object drug is the one affected by the interaction; Dr. Smith said it is the one being bullied."},
  {t:"The substrate drug", correct:false, why:"Substrate is a column in the CYP450 table; it is not the name for the cause of an interaction."},
  {t:"The incompatible drug", correct:false, why:"Incompatibility describes drugs mixed outside the body, such as in an IV bag."}],
 teach:"The precipitant drug is the drug, chemical or food that causes the interaction (the bad guy). The object drug is the one whose effect or levels are changed (the one being bullied). In the Engelbrecht and Shargel tables the middle column lists precipitants.",
 quote:"The precipitant drug is the drug, or the chemical, or the food substance that's causing the interaction. OK, so it's the bad guy, it's, it's causing the problem, and the object drug is the one that's being bullied or affected by the precipitant drug.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Drug Interactions Introduction' (p. 5); (T) 10/28 transcript"},

{id:"L22-044", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-intro", skill:"recall",
 concept:"same-drug-both-roles", tags:["smith"], source:"both",
 stem:"Dr. Smith used valproic acid in two plasma protein binding examples, one with phenytoin and one with aspirin. What point did she make about valproic acid?",
 options:[
  {t:"One drug can be precipitant in one pair and object in another", correct:true, why:"Valproic acid is the precipitant with phenytoin and the object drug with aspirin."},
  {t:"Valproic acid is the object drug in both pairs", correct:false, why:"With phenytoin, valproic acid does the displacing, so there it is the precipitant."},
  {t:"Valproic acid is the precipitant drug in both pairs", correct:false, why:"Aspirin displaces valproic acid, so in that pair valproic acid is the object drug."},
  {t:"A drug's role in an interaction is set by its drug class", correct:false, why:"The role depends on which drug it is paired with, not its class."}],
 teach:"Valproic acid displaces phenytoin from plasma proteins, so with phenytoin it is the precipitant. Aspirin displaces valproic acid, so there valproic acid is the object drug. The role depends on the pairing.",
 quote:"So depending on the two drugs playing together. Sometimes one might be the precipitant, and sometimes that same one could be an object drug, depending on who it's playing with.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Distribution' (p. 11); (T) 10/28 transcript"},

{id:"L22-045", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-intro", skill:"tell",
 concept:"pharmaceutical-incompatibility", tags:["smith"], source:"both",
 stem:"Drug interactions are classified as pharmacokinetic, pharmacodynamic or pharmaceutical. What is a pharmaceutical interaction?",
 options:[
  {t:"An incompatibility when drugs are mixed, as in making IVs", correct:true, why:"Pharmaceutical interactions are incompatibilities outside the body; Dr. Smith gave incompatible drugs when making IVs as the example."},
  {t:"A change in a drug's absorption, distribution, metabolism or excretion", correct:false, why:"A change in ADME (absorption, distribution, metabolism, excretion) by another substance is a pharmacokinetic interaction."},
  {t:"A change in a drug's effect at its target by another substance", correct:false, why:"An altered effect is a pharmacodynamic interaction."},
  {t:"Any interaction between a drug and a manufactured food", correct:false, why:"Food-drug interactions in the body are pharmacokinetic or pharmacodynamic."}],
 teach:"A pharmacokinetic interaction changes a drug's ADME (absorption, distribution, metabolism or excretion); a pharmacodynamic interaction changes its effect. A pharmaceutical interaction is an incompatibility when drugs are mixed outside the body, as when making IVs.",
 quote:"you are aware that there are other kinds of drug interactions that occur outside the body. Things like, you know, incompatible drugs when you're trying to make IVs",
 cite:"DDI Lecture Students 2026 (1).pdf slides 'Objectives' (p. 3) and 'Drug Interactions Introduction' (p. 6); (T) 10/28 transcript"},

{id:"L22-046", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-pd", skill:"recall",
 concept:"pd-classification-effects", tags:["smith"], source:"slide",
 stem:"A pharmacodynamic interaction alters the effect of a drug through another drug, chemical or food element. Which combined effects does the classification name?",
 options:[
  {t:"Antagonistic, synergistic or additive", correct:true, why:"These three are the effects named in the pharmacodynamic definition."},
  {t:"Absorption, distribution or excretion changes", correct:false, why:"Changes in ADME define a pharmacokinetic interaction."},
  {t:"Induction, inhibition or substrate competition", correct:false, why:"These are the ways metabolism and clearance are changed, a pharmacokinetic topic."},
  {t:"Precipitation, flocculation or color change", correct:false, why:"Physical changes on mixing belong to pharmaceutical incompatibility."}],
 teach:"A pharmacodynamic interaction alters a drug's effect through another drug, chemical or food element, producing an antagonistic, synergistic or additive effect. Her four situations: similar actions, opposite effects, an adverse effect that raises sensitivity to another drug, and opposite effects at the same target.",
 note:"Dr. Smith did not read the words additive, synergistic or antagonistic aloud in this part; they are on p. 6. The toxicology bank (L14-040) covers additive, synergistic, potentiation and antagonistic interactions between toxicants.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Drug Interactions Introduction' (p. 6)"},

/* ---------------- Pharmacokinetic interactions: absorption (pp. 8-10) ---------------- */
{id:"L22-047", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-absorb", skill:"apply", core:true, coreWhy:"her absorption table (Table 18-1), which she said to learn",
 concept:"absorption-ddi-outside-gi", tags:["smith"], source:"transcript",
 stem:"A dentist adds epinephrine to a local anesthetic so the anesthetic stays at the injection site, and the patient becomes shaky. What kind of drug interaction is this?",
 options:[
  {t:"An absorption interaction outside the GI tract", correct:true, why:"Epinephrine keeps the anesthetic localized, changing its absorption at a site outside the gut."},
  {t:"A distribution interaction at plasma proteins", correct:false, why:"Nothing is displaced from plasma proteins here; the effect is on absorption at the site."},
  {t:"A pharmacodynamic interaction at the same receptor", correct:false, why:"The drugs do not act on a shared receptor; the interaction is on absorption."},
  {t:"A pharmaceutical incompatibility in the syringe", correct:false, why:"The two are given together on purpose; there is no incompatibility."}],
 teach:"An absorption interaction changes the rate and extent of a drug's absorption from its site, and so its bioavailability. The GI tract is the most common site, but not the only one. Epinephrine given with Novocaine keeps the anesthetic localized, an absorption interaction outside the gut; the epinephrine made her shaky.",
 quote:"She goes, no, no, we just gave you epinephrine with your Novocaine to try to keep it more localized and right there in the area. So there, that's a drug interaction, not in the GI tract, OK?",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Absorption' (p. 8); (T) 10/28 transcript"},

{id:"L22-048", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-absorb", skill:"recall", core:true, coreWhy:"her absorption table (Table 18-1), which she said to learn",
 concept:"chelation-levofloxacin", tags:["smith"], source:"both",
 stem:"Levofloxacin is taken with a calcium, magnesium, aluminum or iron salt. What type of interaction is this, and what is the effect?",
 options:[
  {t:"Complexation (chelation); lower bioavailability", correct:true, why:"Levofloxacin complexes with the divalent cations, so less is absorbed."},
  {t:"Adsorption; lower bioavailability", correct:false, why:"Adsorption is the looser binding to cholestyramine, kaolin, activated charcoal or acarbose."},
  {t:"Complexation (chelation); higher bioavailability", correct:false, why:"The complex is not absorbed, so bioavailability goes down."},
  {t:"Enzyme induction; faster metabolism", correct:false, why:"The cations act in the gut by binding the drug, not on enzymes."}],
 teach:"Calcium, magnesium, aluminum and iron salts complex with levofloxacin, a quinolone; the complex is not absorbed, so bioavailability falls. Complexation and chelation are the tighter bonding, unlike adsorption.",
 quote:"The complex complexation and chelation is gonna be more of your covalent type bonding, OK?",
 cite:"DDI Lecture Students 2026 (1).pdf slides 'Pharmacokinetic Interactions: Absorption' (p. 9, Table 18-1) and 'Food-Drug Interactions' (p. 26); (T) 10/28 transcript"},

{id:"L22-049", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-absorb", skill:"apply", core:true, coreWhy:"her absorption table (Table 18-1), which she said to learn",
 concept:"magnesium-quinolone-counsel", tags:["smith","inclass"], source:"transcript",
 stem:"A patient takes a magnesium supplement for sleep and is prescribed a quinolone antibiotic. What counseling is needed?",
 options:[
  {t:"Separate the two by several hours", correct:true, why:"She said to give one compound time to get through before the next goes in."},
  {t:"Take them together with food", correct:false, why:"Taking them together lets the magnesium complex the quinolone."},
  {t:"Stop the antibiotic until the magnesium is finished", correct:false, why:"She did not stop either one; she spaced them apart."},
  {t:"Double the antibiotic dose", correct:false, why:"She gave no dose change; spacing the doses was her answer."}],
 teach:"Quinolones complex with positively charged ions such as magnesium. Counsel the patient to separate the two by several hours, so one compound clears before the next goes in; nothing is stopped and no dose changes.",
 quote:"Um, you would be needing to counsel them and say you need to separate them by several hours.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions: Absorption' (p. 9, Table 18-1); (T) 10/28 transcript"},

{id:"L22-050", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-absorb", skill:"tell", core:true, coreWhy:"her absorption table (Table 18-1), which she said to learn",
 concept:"adsorption-vs-absorption", tags:["smith"], source:"both",
 stem:"Cholestyramine lowers the bioavailability of digoxin and levothyroxine. Under which drug interaction type does the absorption table (Table 18-1) list it?",
 options:[
  {t:"Adsorption", correct:true, why:"Adsorption, with a D: the drugs stick to cholestyramine by a looser bond, like van der Waals forces."},
  {t:"Absorption", correct:false, why:"Absorption, with a B, is the process being changed, not the name of this interaction."},
  {t:"Chelation", correct:false, why:"Chelation is the tighter, covalent-type bonding, as with levofloxacin and cations."},
  {t:"Enzyme induction", correct:false, why:"Cholestyramine binds the drugs in the gut; it does not change enzymes."}],
 teach:"Adsorption (with a D) means a drug sticks to another compound by a looser bond, such as van der Waals forces, without chemically binding. Cholestyramine adsorbs digoxin and levothyroxine and lowers their bioavailability. Absorption (with a B) is the process being changed.",
 quote:"Remember, adsorption means, for example, your digoxin or levothyroxine is sticking to cholestyramine, OK? It's not chemically binding to it, really.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions: Absorption' (p. 9, Table 18-1); (T) 10/28 transcript"},

{id:"L22-051", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-absorb", skill:"recall", multi:true, core:true, coreWhy:"her absorption table (Table 18-1), which she said to learn",
 concept:"adsorption-precipitants", tags:["smith"], source:"slide",
 stem:"Which precipitants are listed under adsorption in the table of interactions that affect bioavailability from the GI tract? Select all that apply.",
 options:[
  {t:"Kaolin", correct:true, why:"Listed under adsorption: decreased bioavailability of digoxin."},
  {t:"Activated charcoal", correct:true, why:"Listed under adsorption: decreased bioavailability of many drugs."},
  {t:"Acarbose", correct:true, why:"Listed under adsorption: decreased bioavailability of digoxin."},
  {t:"Erythromycin", correct:false, why:"Erythromycin is under alteration of intestinal flora, and it raises digoxin bioavailability."},
  {t:"Sodium polystyrene sulfonate", correct:false, why:"Listed under complexation/chelation: it binds the cations in antacids."},
  {t:"Levofloxacin", correct:false, why:"Levofloxacin is an object drug chelated by cations, not an adsorbent precipitant."}],
 teach:"Table 18-1 lists four adsorbents: cholestyramine (digoxin, levothyroxine), kaolin (digoxin), activated charcoal (many drugs) and acarbose (digoxin). Each lowers the object drug's bioavailability. Learn this table.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions: Absorption' (p. 9, Table 18-1)"},

{id:"L22-052", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-absorb", skill:"recall", core:true, coreWhy:"her absorption table (Table 18-1), which she said to learn",
 concept:"erythromycin-digoxin-flora", tags:["smith"], source:"slide",
 stem:"How does erythromycin change the oral bioavailability of digoxin?",
 options:[
  {t:"Raises it; fewer gut bacteria inactivate digoxin", correct:true, why:"Erythromycin reduces the intestinal flora that inactivate digoxin, so more is available."},
  {t:"Lowers it; erythromycin adsorbs digoxin", correct:false, why:"The adsorbents for digoxin are cholestyramine, kaolin and acarbose."},
  {t:"Lowers it; erythromycin speeds GI motility", correct:false, why:"Increased motility is the laxative and cathartic row."},
  {t:"No change; erythromycin changes digoxin's renal clearance instead", correct:false, why:"The interaction is in the gut, under alteration of intestinal flora, not the kidney."}],
 teach:"Under alteration of intestinal flora, antibiotics are the precipitants. Gut bacteria inactivate part of a digoxin dose; erythromycin reduces those bacteria, so more digoxin is available and its bioavailability rises.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions: Absorption' (p. 9, Table 18-1)"},

{id:"L22-053", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-absorb", skill:"apply", core:true, coreWhy:"her absorption table (Table 18-1), which she said to learn",
 concept:"antibiotics-oral-contraceptive", tags:["smith"], source:"both",
 stem:"A woman taking an estrogen/progestin oral contraceptive is given an antibiotic. What is the concern, and through what process?",
 options:[
  {t:"Subtherapeutic hormone levels; less enterohepatic circulation", correct:true, why:"Fewer gut bacteria means less of the hormone is processed for enterohepatic circulation and reabsorbed."},
  {t:"Hormone toxicity; slower metabolism of the hormones by the liver", correct:false, why:"Levels fall, not rise; the change is in the gut flora."},
  {t:"Subtherapeutic hormone levels; chelation of the hormones", correct:false, why:"Chelation is the cation-quinolone row; antibiotics act here by changing the flora."},
  {t:"No concern; the hormones are absorbed before the antibiotic acts", correct:false, why:"The interaction is in the gut flora and enterohepatic recycling, not a race with absorption."}],
 teach:"Estrogen/progestin birth control depends on intestinal flora: gut bacteria metabolize the hormones to forms that undergo enterohepatic circulation and are reabsorbed. Antibiotics reduce the flora, so less hormone is reabsorbed, levels fall, and ovulation suppression can fail.",
 quote:"So that's why women could be subtherapeutic on an oral contraceptive if they're taking antibiotics, OK.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions: Absorption' (p. 9, Table 18-1); (T) 10/28 transcript"},

{id:"L22-054", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-absorb", skill:"apply", core:true, coreWhy:"her absorption table (Table 18-1), which she said to learn",
 concept:"gastric-ph-ketoconazole", tags:["smith"], source:"both",
 stem:"A patient on a proton pump inhibitor is started on oral ketoconazole. What can happen to the ketoconazole?",
 options:[
  {t:"Less dissolves; absorption falls and therapy can fail", correct:true, why:"The proton pump inhibitor raises gastric pH, and ketoconazole dissolves less at basic pH."},
  {t:"It is adsorbed onto the proton pump inhibitor in the stomach", correct:false, why:"Adsorption is the cholestyramine, kaolin, charcoal and acarbose row."},
  {t:"More dissolves; levels rise toward toxicity", correct:false, why:"Dissolution of ketoconazole is reduced at basic pH, not increased."},
  {t:"Its metabolism in intestinal cells is blocked", correct:false, why:"Inhibition of metabolism in intestinal cells is the monoamine oxidase inhibitor row."}],
 teach:"H2-blockers, antacids and proton pump inhibitors raise gastric pH. Ketoconazole dissolves poorly at basic pH, so less is absorbed and therapy can fail. Foods that raise stomach pH do the same.",
 quote:"if you are doing, uh, ingesting things that'll raise the pH of the stomach, you may change the bioavailability of drugs that need to stay at a certain valence to be absorbed from the stomach.",
 cite:"DDI Lecture Students 2026 (1).pdf slides 'Pharmacokinetic Interactions: Absorption' (p. 9, Table 18-1) and 'Food-Drug Interactions' (p. 26); (T) 10/28 transcript"},

{id:"L22-055", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-absorb", skill:"tell", core:true, coreWhy:"her absorption table (Table 18-1), which she said to learn",
 concept:"gi-motility-rows", tags:["smith"], source:"slide",
 stem:"Propantheline, an anticholinergic, is given with acetaminophen. What happens to acetaminophen?",
 options:[
  {t:"Acetaminophen absorption is delayed", correct:true, why:"Propantheline decreases gastric emptying, delaying acetaminophen's absorption from the small intestine."},
  {t:"Acetaminophen is adsorbed and lost in the stool", correct:false, why:"Adsorption is a different row; propantheline acts on motility."},
  {t:"Controlled-release acetaminophen passes through too fast", correct:false, why:"Faster transit is the increased-motility row for laxatives and cathartics."},
  {t:"Acetaminophen absorption is unchanged", correct:false, why:"The table lists a delay in absorption."}],
 teach:"Decreased GI motility: anticholinergics such as propantheline slow gastric emptying, which delays acetaminophen's absorption from the small intestine. Increased GI motility: laxatives and cathartics lower the bioavailability of slowly absorbed and controlled-release drugs.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions: Absorption' (p. 9, Table 18-1)"},

{id:"L22-056", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-absorb", skill:"recall",
 concept:"carrier-competition-pgp", tags:["smith"], source:"both",
 stem:"Besides changes in intestinal blood flow, which other GI absorption interaction involves a carrier such as P-gp?",
 options:[
  {t:"Competition for the same carrier, such as P-gp", correct:true, why:"A precipitant that competes for the object drug's carrier, such as P-glycoprotein (P-gp), changes its bioavailability."},
  {t:"Displacement from plasma proteins", correct:false, why:"Plasma protein displacement is a distribution interaction."},
  {t:"Blocking active tubular secretion in the kidney", correct:false, why:"Tubular secretion is part of renal clearance, not absorption."},
  {t:"Induction of CYP1A2 in the liver", correct:false, why:"Hepatic induction affects metabolism and clearance."}],
 teach:"Two more interactions change GI bioavailability: competition for carrier-mediated absorption, where the precipitant competes for the object drug's carrier (think P-glycoprotein, P-gp), and a change in intestinal blood flow. Blood-flow changes are rare; motility changes matter more.",
 quote:"So think about PGP. OK? If you've got a precipitant drug that messes around with the PGP's ability to do its right thing with your object drug, then you could change the bioavailability of your object drug, OK?",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Absorption' (p. 10); (T) 10/28 transcript"},

/* ---------------- Pharmacokinetic interactions: distribution (pp. 11-12) ---------------- */
{id:"L22-057", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-distrib", skill:"apply",
 concept:"valproate-displaces-phenytoin", tags:["smith"], source:"both",
 stem:"A patient at steady state on phenytoin has breakthrough seizures, and valproic acid is added. What is the concern?",
 options:[
  {t:"More free phenytoin and its side effects", correct:true, why:"Valproic acid binds plasma proteins better and knocks phenytoin off, so more phenytoin is free."},
  {t:"Less free valproic acid and no seizure control", correct:false, why:"Valproic acid is the one that binds better; it is phenytoin that is displaced."},
  {t:"Faster phenytoin metabolism by enzyme induction", correct:false, why:"The example is protein binding displacement, not induction."},
  {t:"No change, as both drugs treat epilepsy", correct:false, why:"Sharing an indication does not prevent a binding interaction."}],
 teach:"Phenytoin is highly protein bound. Valproic acid binds plasma proteins better, so it displaces phenytoin. More phenytoin is free, and phenytoin has a narrow therapeutic index, so side effects can follow.",
 quote:"So, valproic acid is gonna kick phenytoin off the plasma proteins and bind there itself. So, phenytoin is a narrow therapeutic index drug.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Distribution' (p. 11); (T) 10/28 transcript"},

{id:"L22-058", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-distrib", skill:"apply",
 concept:"aspirin-displaces-valproate", tags:["smith"], source:"both",
 stem:"A patient whose epilepsy is controlled on valproic acid at steady state takes some aspirin. What happens?",
 options:[
  {t:"More valproic acid becomes free", correct:true, why:"Aspirin decreases valproic acid protein binding; it bumps valproic acid off."},
  {t:"Aspirin becomes more free", correct:false, why:"Aspirin is the precipitant here; valproic acid is the object drug."},
  {t:"Valproic acid binds more tightly", correct:false, why:"Its protein binding decreases."},
  {t:"Valproic acid is chelated in the gut", correct:false, why:"This is a distribution interaction on plasma proteins."}],
 teach:"Aspirin lowers valproic acid protein binding: it bumps valproic acid off the plasma proteins, so more is free. Displaced free drug can become supratherapeutic or go elsewhere and cause side effects.",
 quote:"But let's say they take some aspirin. Aspirin bumps valproic acid off. OK. So now more valproic acid is free.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Distribution' (p. 11); (T) 10/28 transcript"},

{id:"L22-059", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-distrib", skill:"apply",
 concept:"quinidine-displaces-digoxin-tissue", tags:["smith"], source:"both",
 stem:"A patient at steady state on digoxin has breakthrough arrhythmias and is given quinidine. What happens to digoxin?",
 options:[
  {t:"It is displaced from muscle and free levels rise", correct:true, why:"Quinidine has an even higher volume of distribution and takes digoxin's place in muscle."},
  {t:"It is displaced from bone and excreted faster", correct:false, why:"Digoxin binds muscle; Dr. Smith corrected herself from bone to muscle."},
  {t:"It is metabolized faster after enzyme induction by quinidine", correct:false, why:"The example is a tissue binding interaction."},
  {t:"Its absorption from the gut is blocked", correct:false, why:"Quinidine acts at the tissue binding sites, not in the gut."}],
 teach:"Tissue binding stays constant at steady state unless another compound competes for the sites. Digoxin has a very high volume of distribution and sticks to muscle; quinidine has an even higher one and displaces it, so free digoxin rises and, with its narrow therapeutic index, the heart can slow too much.",
 quote:"It'll displace your digoxin from the muscle tissue, and the quinidine is gonna bind to the muscle, OK?",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Distribution' (p. 12); (T) 10/28 transcript"},

/* ---------------- Pharmacokinetic interactions: metabolism and clearance (pp. 13-15) ---------------- */
{id:"L22-060", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-metab", skill:"recall", multi:true,
 concept:"metabolism-clearance-mechanisms", tags:["smith"], source:"both",
 stem:"Which mechanisms can a precipitant use to change hepatic metabolism and clearance of an object drug? Select all that apply.",
 options:[
  {t:"Enzyme induction", correct:true, why:"One of the four listed mechanisms."},
  {t:"Enzyme inhibition", correct:true, why:"One of the four listed mechanisms."},
  {t:"Substrate competition for the same enzyme", correct:true, why:"One of the four listed mechanisms."},
  {t:"Changes in hepatic blood flow", correct:true, why:"One of the four listed mechanisms."},
  {t:"Changes in tubular reabsorption in the kidney", correct:false, why:"Tubular reabsorption is one of the renal mechanisms, not hepatic."},
  {t:"Displacement from plasma proteins", correct:false, why:"Plasma protein displacement is a distribution interaction, not a hepatic clearance mechanism."}],
 teach:"A precipitant can change hepatic metabolism and clearance by enzyme induction, enzyme inhibition, substrate competition for the same enzyme, or changes in hepatic blood flow. The liver is simpler than the kidney: mostly inhibition and induction.",
 quote:"You guys already know that metabolism clearance may be affected by enzyme induction, or enzyme inhibition, substrate competition for the same enzyme, or changes in hepatic blood flow.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Drug Elimination and Clearance' (p. 13); (T) 10/28 transcript"},

{id:"L22-061", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-metab", skill:"apply",
 concept:"smoking-theophylline-child", tags:["smith","inclass"], source:"both",
 stem:"A child with asthma is treated with theophylline and lives in a household where people smoke. Is the child more likely subtherapeutic or in an overdose situation?",
 options:[
  {t:"Subtherapeutic", correct:true, why:"The smoke induces the enzymes that metabolize and clear theophylline."},
  {t:"Overdose", correct:false, why:"Induction speeds clearance, so levels fall rather than rise."},
  {t:"Neither; smoke exposure does not affect theophylline", correct:false, why:"The smoke is the precipitant in this classic example."},
  {t:"Overdose, then subtherapeutic once smoke clears", correct:false, why:"Dr. Smith gave a single answer: the child is subtherapeutic."}],
 teach:"Cigarette smoke contains polycyclic aromatic hydrocarbons (PAHs), which induce CYP1A1 and CYP1A2. Theophylline is metabolized by these enzymes, so a child exposed to smoke clears it faster and is subtherapeutic. This made asthmatic children in smoking households hard to treat.",
 quote:"And we finally realized that cigarette smoke, the PAHs, were inducing those enzymes that metabolize theophylline, so we always had a hard time treating these kids.",
 cite:"DDI Lecture Students 2026 (1).pdf slides 'Pharmacokinetic Interactions Drug Elimination and Clearance' (p. 14, Table 18-2) and 'Chemical-Drug Interactions' (p. 29); (T) 10/28 transcript"},

{id:"L22-062", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-metab", skill:"apply",
 concept:"phenytoin-induces-tacrolimus", tags:["smith"], source:"both",
 stem:"A transplant patient on tacrolimus, a calcineurin inhibitor, is started on phenytoin. What happens to tacrolimus?",
 options:[
  {t:"Levels fall; CYP3A is induced", correct:true, why:"Phenytoin induces CYP3A4 and CYP3A5, which metabolize tacrolimus."},
  {t:"Levels rise; CYP3A is inhibited", correct:false, why:"Phenytoin is the classic inducer in this table, not an inhibitor."},
  {t:"Levels fall; tacrolimus is adsorbed", correct:false, why:"The table places this pair under enzyme induction."},
  {t:"Levels rise; protein binding falls", correct:false, why:"Protein binding displacement is the phenytoin and valproic acid example, a different pair."}],
 teach:"Phenytoin, an antiepileptic, induces several enzyme families, including CYP3A4 and CYP3A5, which metabolize tacrolimus. More enzyme means faster metabolism, so tacrolimus levels fall.",
 quote:"Penytoin will induce the cytochrome P4503A's, like 3A4, 3A5, and those are the enzymes that help us metabolize and cure clear tacrolimus.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Drug Elimination and Clearance' (p. 14, Table 18-2); (T) 10/28 transcript"},

{id:"L22-063", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-metab", skill:"apply",
 concept:"cimetidine-atorvastatin", tags:["smith","inclass"], source:"both",
 stem:"A patient with gastroesophageal reflux disease (GERD) takes cimetidine and is also on atorvastatin. What is the interaction?",
 options:[
  {t:"Enzyme inhibition; atorvastatin levels rise", correct:true, why:"Cimetidine inhibits the enzymes that clear the statin, so atorvastatin clearance falls."},
  {t:"Enzyme induction; atorvastatin levels fall", correct:false, why:"Cimetidine is the historic inhibitor, not an inducer."},
  {t:"Displacement of cimetidine from plasma proteins", correct:false, why:"Atorvastatin is the object drug, and the mechanism is enzyme inhibition."},
  {t:"Chelation; less atorvastatin absorbed", correct:false, why:"Chelation is the quinolone and cation example."}],
 teach:"Cimetidine, one of the first GERD drugs, inhibits the mixed-function oxidase enzymes that clear atorvastatin. Clearance falls, so atorvastatin levels rise. It is the historic example of enzyme inhibition.",
 quote:"We did a lot of work trying to understand how inhibition happens by using cimetidine and looking at atorvastatin clearance.",
 note:"The caption reads \"It has a really wide narrowtherapeutic index\"; from context Dr. Smith meant cimetidine has a wide therapeutic index, so large amounts usually cause no problems. That sentence is not quoted.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Drug Elimination and Clearance' (p. 14, Table 18-2); (T) 10/28 transcript"},

{id:"L22-064", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-metab", skill:"apply",
 concept:"maoi-tyramine-crisis", tags:["smith"], source:"both",
 stem:"A patient taking a monoamine oxidase inhibitor (MAOI) such as tranylcypromine eats cheddar cheese and drinks red wine. What can result?",
 options:[
  {t:"A hypertensive crisis", correct:true, why:"The MAOI blocks the clearance of tyramine from these foods, and tyramine raises blood pressure."},
  {t:"A hypotensive collapse", correct:false, why:"Tyramine is a pressor substance; blood pressure goes up."},
  {t:"Serotonin syndrome from the cheese", correct:false, why:"The listed outcome is hypertensive crisis from tyramine."},
  {t:"Loss of the antidepressant effect", correct:false, why:"The risk named is blood pressure, not therapeutic failure."}],
 teach:"MAOIs, a class of antidepressants, block the normal metabolism of catecholamines and also of tyramine from foods such as cheddar cheese, red wine and avocado. Tyramine raises blood pressure, so the excess can cause a hypertensive crisis.",
 quote:"if you've got patients on a monoine oxidase inhibitor type of medication, that's going to inhibit the clearance of the tyramines in those foods, and you end up with your patient having screaming high blood pressure.",
 cite:"DDI Lecture Students 2026 (1).pdf slides 'Pharmacokinetic Interactions Drug Elimination and Clearance' (p. 14, Table 18-2) and 'Food-Drug Interactions' (p. 28); (T) 10/28 transcript"},

{id:"L22-065", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-metab", skill:"recall", multi:true,
 concept:"non-drug-cyp-precipitants", tags:["smith","inclass"], source:"both",
 stem:"Which of these non-drug precipitants appear in the cytochrome P450 inducer and inhibitor table? Select all that apply.",
 options:[
  {t:"Garlic", correct:true, why:"A student named garlic first; the table lists garlic supplements in the CYP3A row."},
  {t:"Charbroiled foods", correct:true, why:"Named by a student; she compared them with cigarette smoke as CYP1A2 inducers."},
  {t:"Grapefruit and Seville oranges", correct:true, why:"She named grapefruit, Seville oranges and bitter oranges in the CYP3A row."},
  {t:"St. John's wort", correct:true, why:"The herbal product the class named; it is listed for CYP2D6 and CYP3A."},
  {t:"Cimetidine, fluoxetine and ritonavir", correct:false, why:"These are drugs, listed as CYP inhibitors."},
  {t:"Red wine and cheddar cheese", correct:false, why:"Tyramine in red wine and aged cheese is the MAOI interaction, not a CYP table entry."}],
 teach:"Table 18-3 lists drug, herb and food actions on cytochrome P450 enzymes. The non-drug precipitants worth knowing: garlic supplements (CYP3A), charbroiled foods (CYP1A2 inducers, like smoke), grapefruit, Seville oranges and bitter oranges (CYP3A), and St. John's wort (CYP2D6 and CYP3A).",
 quote:"Can you find some of the precipitants, ones that are either inhibitors or inducers that are not drugs? Hmm. Garlic, yeah.",
 note:"She said the non-drug examples \"all just happen to be inducers\" and that the citrus fruits \"will induce\" the 3A family. In the printed table these items sit under the Inducer heading for CYP3A. Later, on food-drug interactions, she said the citrus compounds \"compete with metabolizing enzymes\", and p. 27 says a competing food acts as an inhibitor. This question does not key the direction; see L22-081.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Drug Elimination and Clearance' (p. 15, Table 18-3); (T) 10/28 transcript"},

{id:"L22-066", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-metab", skill:"recall",
 concept:"st-johns-wort-induces", tags:["smith","inclass"], source:"both",
 stem:"St. John's wort is an herbal product people use for depression. Which enzymes does the cytochrome P450 table list it as inducing?",
 options:[
  {t:"CYP2D6 and CYP3A4", correct:true, why:"The table lists St. John's wort as an inducer of CYP2D6 and of the CYP3A family."},
  {t:"CYP1A2 and CYP2E1", correct:false, why:"Smoking and charbroiled foods induce CYP1A2; ethanol induces CYP2E1."},
  {t:"CYP2C9 and CYP2C19", correct:false, why:"The 2C inducers listed are drugs such as rifampin and carbamazepine."},
  {t:"None; it inhibits CYP3A4", correct:false, why:"It is listed as an inducer, not an inhibitor."}],
 teach:"St. John's wort is taken for depression, has real activity and a lot of potential for drug interactions. Table 18-3 lists it as an inducer of CYP2D6 and CYP3A4; the St. John's wort table adds CYP2C9, CYP1A2 and intestinal P-glycoprotein.",
 quote:"Saint John's wort is noted to be an inducer of SIP 2D6 and also SIP 3A4.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Drug Elimination and Clearance' (p. 15, Table 18-3); (T) 10/28 transcript"},

/* ---------------- Pharmacokinetic interactions: renal clearance (pp. 16-17) ---------------- */
{id:"L22-067", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-renal", skill:"recall", multi:true,
 concept:"renal-clearance-mechanisms", tags:["smith"], source:"both",
 stem:"A patient is stable on an object drug cleared by the kidney. Which ways can an added precipitant change its renal clearance? Select all that apply.",
 options:[
  {t:"Changing the GFR", correct:true, why:"Changes in glomerular filtration rate (GFR) are on the list."},
  {t:"Changing tubular reabsorption", correct:true, why:"On the list."},
  {t:"Changing active tubular secretion", correct:true, why:"On the list."},
  {t:"Being nephrotoxic", correct:true, why:"On the list."},
  {t:"Displacing it from plasma proteins in the blood", correct:false, why:"Plasma protein displacement is a distribution interaction."},
  {t:"Inducing hepatic CYP3A", correct:false, why:"Inducing a hepatic enzyme changes metabolism, not renal clearance."}],
 teach:"A precipitant can affect renal clearance by changing GFR, tubular reabsorption or active tubular secretion, or by being nephrotoxic. The kidney's anatomy and physiology give precipitants places to act that are unique to that organ, unlike the liver.",
 quote:"that precipitant drug could change the GFR. Could change tubular reabsorption, it could change tubular secretion, or it could actually be nephrotoxic.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Drug Elimination and Clearance' (p. 16); (T) 10/28 transcript"},

{id:"L22-068", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-renal", skill:"recall",
 concept:"caffeine-gfr", tags:["smith"], source:"both",
 stem:"Methylxanthines such as caffeine act as precipitants in the kidney. What do they change, and with what result?",
 options:[
  {t:"Raise GFR; faster urinary excretion", correct:true, why:"More renal blood flow and GFR leave less time for reabsorption, so drugs are excreted faster."},
  {t:"Block tubular secretion; higher levels", correct:false, why:"Blocking tubular secretion is the probenecid row."},
  {t:"Alkalinize the urine; more reabsorption", correct:false, why:"Alkalinizing the urine is the antacid and sodium bicarbonate row."},
  {t:"Lower GFR; slower urinary excretion", correct:false, why:"Methylxanthines increase renal blood flow and GFR."}],
 teach:"Methylxanthines (caffeine, theobromine) increase renal blood flow and GFR. That leaves less time for reabsorption of various drugs, so they are excreted in the urine faster. The caffeine she drinks could change the kinetics of a drug that depends on GFR.",
 quote:"So, all the caffeine I drink as I come here to lecture for you guys is changing my GFR.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Drug Elimination and Clearance' (p. 17, Table 18-4); (T) 10/28 transcript"},

{id:"L22-069", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-renal", skill:"apply",
 concept:"probenecid-penicillin-levels", tags:["smith","inclass"], source:"both",
 stem:"Probenecid is given with penicillin. Do the blood concentrations of the antibiotic go up or down, and is that good for treating the infection?",
 options:[
  {t:"Up; yes, for treating the infection", correct:true, why:"Probenecid blocks the active tubular secretion of penicillin, so blood levels rise, which helps treat the infection."},
  {t:"Down; no, the infection is undertreated", correct:false, why:"Secretion is blocked, so less penicillin leaves in the urine."},
  {t:"Up; no, penicillin toxicity is the goal to avoid", correct:false, why:"Dr. Smith called the higher level good for fighting the infection."},
  {t:"No change; the two use different transporters", correct:false, why:"Dr. Smith said probenecid goes through the same transporter as the antibiotic."}],
 teach:"Secretion of penicillins and some cephalosporins into the urine is active transport. Probenecid uses the same transporter and blocks the antibiotic from being secreted, so blood concentrations go up, which helps treat the infection. Historically this stretched scarce penicillin.",
 quote:"So what happens then? Do the blood concentrations of the antibiotic go up or down? Up. Is that good for fighting an infection? Yeah, you want your MIC to be high, right?",
 cite:"DDI Lecture Students 2026 (1).pdf slides 'Pharmacokinetic Interactions Drug Elimination and Clearance' (p. 17, Table 18-4) and 'Benefits (!) of Drug-Drug Interactions' (p. 21); (T) 10/28 transcript"},

{id:"L22-070", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-renal", skill:"apply", dupOf:"L16-024",
 concept:"alkalinize-urine-salicylate", tags:["smith"], source:"both",
 stem:"Sodium bicarbonate is given to a patient with a salicylate overdose. What happens to the salicylate in the urine?",
 options:[
  {t:"More ionized, less reabsorbed, cleared faster", correct:true, why:"Alkaline urine ionizes the mildly acidic salicylate, so it is trapped in the urine."},
  {t:"Less ionized, more reabsorbed, cleared slower", correct:false, why:"That is the direction Table 18-4 lists for amphetamine."},
  {t:"Bound to bicarbonate and adsorbed", correct:false, why:"The bicarbonate changes urine pH; it does not adsorb the drug."},
  {t:"Secreted faster by the probenecid transporter", correct:false, why:"Probenecid blocks secretion of penicillins; this row is about urine pH."}],
 teach:"Antacids and sodium bicarbonate alkalinize the urine. Salicylate is a mild acid, so alkaline urine ionizes it; the ionized form is not reabsorbed and is trapped in the urine, so clearance rises. This is the ion trapping from toxicology.",
 quote:"We talked about alkalization of the urine. To increase the ionization of things like salicylates, so your mildly acidic poisoning poisons",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Drug Elimination and Clearance' (p. 17, Table 18-4); (T) 10/28 transcript"},

{id:"L22-071", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-renal", skill:"apply",
 concept:"alkalinize-urine-amphetamine", tags:["smith"], source:"both",
 stem:"Antacids or sodium bicarbonate alkalinize the urine of a patient taking amphetamine. What happens to amphetamine?",
 options:[
  {t:"More reabsorbed; clearance falls", correct:true, why:"The table lists increased reabsorption and decreased clearance of amphetamine."},
  {t:"Less reabsorbed; clearance rises", correct:false, why:"That is the salicylate direction, for a mildly acidic drug."},
  {t:"Secretion is blocked; levels fall", correct:false, why:"Blocked secretion raises levels, and that row is probenecid."},
  {t:"No change; urine pH does not matter", correct:false, why:"Urine pH changes the reabsorption of amphetamine."}],
 teach:"Alkalinizing the urine increases the reabsorption of amphetamine, a base, and decreases its clearance, the opposite of the salicylate direction. It could be useful in ADHD (attention-deficit/hyperactivity disorder), though it is not commonly done.",
 quote:"I did not talk in class during our toxicology lectures about alkalizing the urine to increase the reabsorption of amphetamine. And decrease its clearance.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacokinetic Interactions Drug Elimination and Clearance' (p. 17, Table 18-4); (T) 10/28 transcript"},

/* ---------------- Pharmacodynamic interactions (pp. 7, 18-20) ---------------- */
{id:"L22-072", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-pd", skill:"recall", multi:true,
 concept:"pd-four-situations", tags:["smith"], source:"both",
 stem:"Which situations are listed as ways pharmacodynamic interactions occur? Select all that apply.",
 options:[
  {t:"Drugs with similar actions give excessive or toxic responses", correct:true, why:"The first situation, such as narcotics with antihistamines."},
  {t:"One drug's effect is antagonized by the opposite effect of another", correct:true, why:"The second situation, such as propranolol with adrenaline."},
  {t:"An adverse effect of one drug raises sensitivity to another", correct:true, why:"The third situation, with different targets, such as potassium-wasting diuretics with digoxin."},
  {t:"Opposite effects on the same target cause therapeutic failure", correct:true, why:"The fourth situation, such as naloxone with a narcotic pain medication."},
  {t:"One drug changes the absorption of another from the gut and its blood levels", correct:false, why:"A change in absorption is a pharmacokinetic interaction."},
  {t:"One drug induces the enzyme that clears another", correct:false, why:"Enzyme induction is a pharmacokinetic interaction, not a pharmacodynamic one."}],
 teach:"Pharmacodynamic interactions occur when drugs with similar actions give excessive or toxic responses, when one drug's effect is antagonized by the opposite effect of another, when an adverse effect of one drug raises sensitivity to another (different targets), and when opposite effects on the same target cause therapeutic failure.",
 quote:"And then you could have a 4th kind of category of a pharmacodynamic effect when the drugs have an opposite effect at the same target, OK, and you could end up with a therapeutic failure.",
 cite:"DDI Lecture Students 2026 (1).pdf slides 'Drug Interactions Introduction' (p. 7) and 'Pharmacodynamic Interactions' (p. 18); (T) 10/28 transcript"},

{id:"L22-073", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-pd", skill:"apply",
 concept:"narcotic-antihistamine-cns", tags:["smith"], source:"both",
 stem:"A patient takes a narcotic pain medication together with an antihistamine. What pharmacodynamic interaction is expected?",
 options:[
  {t:"More CNS depression (drowsiness)", correct:true, why:"Both are central nervous system (CNS) depressants with similar actions, so the sedation adds up."},
  {t:"The narcotic stops working", correct:false, why:"Loss of narcotic effect is the naloxone example, opposite effects at the same target."},
  {t:"Raised blood pressure from both drugs", correct:false, why:"Neither drug class raises blood pressure in these examples."},
  {t:"Less CNS depression (alertness)", correct:false, why:"Similar actions give an excessive response, not a cancelled one."}],
 teach:"Narcotics and antihistamines are both CNS depressants. Together these similar pharmacodynamic actions produce increased CNS depression: people taking the two are going to be really sleepy.",
 quote:"You give those two drugs together, those two categories of drugs together, and people are gonna be really sleepy, OK?",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacodynamic Interactions Examples' (p. 19); (T) 10/28 transcript"},

{id:"L22-074", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-pd", skill:"recall", multi:true,
 concept:"promethazine-antihistamine-anticholinergic", tags:["smith"], source:"both",
 stem:"Promethazine is given with an antihistamine. Which effects increase? Select all that apply.",
 options:[
  {t:"Dry mouth", correct:true, why:"An anticholinergic effect listed for this pair."},
  {t:"Blurred vision", correct:true, why:"An anticholinergic effect listed for this pair."},
  {t:"Urinary retention", correct:true, why:"An anticholinergic effect listed for this pair."},
  {t:"Diarrhea", correct:false, why:"Anticholinergic effects slow the gut; diarrhea is not listed."},
  {t:"Excess salivation", correct:false, why:"Anticholinergic effects dry the mouth."},
  {t:"Bradycardia", correct:false, why:"Anticholinergic effects tend to raise heart rate, not slow it."}],
 teach:"Promethazine and antihistamines both have anticholinergic actions. Together they increase anticholinergic effects: excessive dry mouth, blurred vision and urinary retention. This is an example of similar pharmacodynamic actions.",
 quote:"Another common example would be the increased anticholinergic effects, so, you know, dry mouth, blurred vision, urinary retention that can happen with something like promethazine and antihistamines, OK?",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacodynamic Interactions Examples' (p. 19); (T) 10/28 transcript"},

{id:"L22-075", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-pd", skill:"tell",
 concept:"antagonism-different-vs-same-receptor", tags:["smith","inclass"], source:"both",
 stem:"Propranolol with adrenaline, and naloxone with a narcotic pain medication: in both pairs the drug effects cancel. How do the two pairs differ?",
 options:[
  {t:"Different receptors in the first; same receptor in the second", correct:true, why:"Adrenaline's vasopressor action is at alpha-1 while propranolol blocks beta; naloxone and the narcotic act at the same receptor."},
  {t:"Same receptor in the first; different receptors in the second", correct:false, why:"This reverses the two pairs."},
  {t:"Both pairs act at the same receptor", correct:false, why:"Dr. Smith asked whether adrenaline works at beta or alpha-1 to show the first pair uses different receptors."},
  {t:"Both pairs are pharmacokinetic interactions", correct:false, why:"Both are pharmacodynamic; neither changes ADME."}],
 teach:"Propranolol with adrenaline is antagonism at different receptors: adrenaline's vasopressor action is at alpha-1 while propranolol blocks beta, and the effects cancel. Naloxone with a narcotic is opposite pharmacodynamics at the same target, making the narcotic ineffective.",
 quote:"It's both, but the alpha one aspect of adrenaline here is, is where we're talking about, it's hitting a different receptor to do the vasopressing",
 cite:"DDI Lecture Students 2026 (1).pdf slides 'Pharmacodynamic Interactions Examples' (pp. 19-20); (T) 10/28 transcript"},

{id:"L22-076", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-pd", skill:"apply",
 concept:"k-wasting-diuretic-digoxin", tags:["smith"], source:"both",
 stem:"A patient stabilized on digoxin is started on a potassium-wasting diuretic. Why is this a problem?",
 options:[
  {t:"Low potassium makes the heart more sensitive to digoxin", correct:true, why:"Falling potassium further blocks the sodium-potassium ATPase that digoxin acts on."},
  {t:"The diuretic displaces digoxin from muscle", correct:false, why:"Displacement from muscle is the quinidine example."},
  {t:"The diuretic induces the liver enzymes that clear digoxin faster", correct:false, why:"This is a pharmacodynamic sensitivity, not a change in metabolism."},
  {t:"High potassium blocks digoxin from its target", correct:false, why:"The diuretic lowers potassium; it does not raise it."}],
 teach:"Digoxin blocks the sodium-potassium ATPase in heart muscle cells. Low potassium blocks that ATPase further, so a patient on digoxin with low potassium is sensitive to too much heart block. A potassium-wasting diuretic lowers potassium and so risks severe digoxin toxicity.",
 quote:"If they're on digoxin, you don't want it to go too low, because that will make you sensitive to too much heart block by digoxin.",
 note:"Dr. Smith first said elevated potassium is looked for in digoxin overdose, then said \"I'm saying that wrong\" and changed it to falling potassium. The question is keyed to the corrected statement and p. 20 (potassium-wasting diuretics + digoxin: potential for severe digoxin toxicity). The toxicology bank (L16) covers digoxin overdose separately.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacodynamic Interactions Examples' (p. 20); (T) 10/28 transcript"},

{id:"L22-077", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-pd", skill:"apply",
 concept:"na-wasting-diuretic-lithium", tags:["smith"], source:"both",
 stem:"A patient with bipolar disorder on lithium is started on a sodium-wasting diuretic and blood sodium falls. What happens to lithium?",
 options:[
  {t:"More is reabsorbed from urine; toxicity", correct:true, why:"Lithium is reabsorbed by the same mechanisms as sodium, and more is taken back when sodium is low."},
  {t:"More is excreted in urine; levels fall too low", correct:false, why:"Low sodium leads to more lithium reabsorption, not more excretion."},
  {t:"It is displaced from plasma proteins", correct:false, why:"The mechanism is renal reabsorption of a positive ion."},
  {t:"Its metabolism by CYP2E1 is induced", correct:false, why:"No enzyme is involved in this example."}],
 teach:"Lithium carries a positive charge like sodium and is reabsorbed from the urine through the same mechanisms. When blood sodium is low, more lithium is reabsorbed too, and with its narrow therapeutic index levels can turn toxic.",
 quote:"So lithium will be reabsorbed from the urine through the same mechanisms that sodium is reabsorbed from the urine, OK.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Pharmacodynamic Interactions Examples' (p. 20); (T) 10/28 transcript"},

/* ---------------- Beneficial interactions and clinical significance (pp. 21-22, 31) ---------------- */
{id:"L22-078", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-benefit", skill:"recall",
 concept:"carbidopa-levodopa", tags:["smith"], source:"both",
 stem:"Why is carbidopa given with levodopa for Parkinson's disease?",
 options:[
  {t:"It blocks peripheral metabolism of levodopa", correct:true, why:"With less levodopa metabolized in the periphery, more reaches the brain intact."},
  {t:"It carries levodopa across the blood-brain barrier", correct:false, why:"Levodopa crosses the blood-brain barrier itself; carbidopa protects it in the periphery."},
  {t:"It induces the enzymes that activate levodopa", correct:false, why:"Carbidopa inhibits, it does not induce."},
  {t:"It blocks levodopa's renal tubular secretion", correct:false, why:"Blocking tubular secretion is the probenecid and penicillin example."}],
 teach:"Levodopa must reach the brain unchanged to work, but it is easily metabolized in the periphery. Carbidopa inhibits that peripheral metabolism, so more levodopa reaches the central nervous system intact. This is a beneficial drug-drug interaction.",
 quote:"The carbidopa will be preventing the metabolism of levodopa, allowing it to be intact and move across the blood-brain barrier to its site of action, OK.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Benefits(!) of Drug-Drug Interactions' (p. 22); (T) 10/28 transcript"},

{id:"L22-079", lecture:"L22", prof:"Smith", tier:"new", lowYield:true, topic:"L22", sub:"ddi-benefit", skill:"recall", multi:true,
 concept:"beneficial-combinations-list", tags:["smith"], source:"slide",
 stem:"Which combinations are listed as drug or drug-food interactions used for a beneficial effect? Select all that apply.",
 options:[
  {t:"Amoxicillin with clavulanate", correct:true, why:"Clavulanate, a beta-lactamase inhibitor, inhibits breakdown of amoxicillin."},
  {t:"HCTZ with triamterene", correct:true, why:"Diuretics with different mechanisms are combined to minimize potassium loss."},
  {t:"Phenytoin with dietary fats", correct:true, why:"The fats increase phenytoin bioavailability by enhanced absorption."},
  {t:"Cimetidine with atorvastatin", correct:false, why:"This is the historic enzyme inhibition example, with raised atorvastatin levels."},
  {t:"A potassium-wasting diuretic with digoxin", correct:false, why:"This raises the risk of severe digoxin toxicity."}],
 teach:"Not all drug interactions are harmful. Some improve a therapeutic objective or reduce adverse effects: trimethoprim with sulfamethoxazole, amoxicillin with clavulanate (a beta-lactamase inhibitor that protects amoxicillin), and HCTZ with triamterene (less potassium loss). Phenytoin with dietary fats, which raise its absorption, is a beneficial drug-food pair.",
 note:"Slide detail only. Dr. Smith left p. 31 for students to read on their own (\"I'll just let you read this slide on your own\"); marked lowYield.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Clinical Significance' (p. 31)"},

/* ---------------- Drug-herbal, food-drug and chemical-drug interactions (pp. 23-30) ---------------- */
{id:"L22-080", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-herb-food", skill:"recall",
 concept:"herbal-interaction-risk", tags:["smith"], source:"both",
 stem:"Herbal products on the US market carry a high potential for drug interactions. Which reason was given?",
 options:[
  {t:"Some have been found to contain prescription drugs", correct:true, why:"Herbal products have been tested and found to contain prescription medications."},
  {t:"They are regulated more tightly than prescription drugs", correct:false, why:"There is little control over herbal products in the US; they are not regulated like drugs."},
  {t:"Each bottle holds a single herb at a fixed potency", correct:false, why:"Bottles often hold more than one plant, and potency varies from batch to batch."},
  {t:"Herbs have no pharmacokinetic or pharmacodynamic activity", correct:false, why:"Herbs can have the same PK and PD effects as drugs and act at the same sites."}],
 teach:"There is little control over herbal products in the US. A bottle labeled as one herb often holds several plants, some products contain prescription drugs or contaminants, and potency varies with harvest, drying and storage. Herbs are pharmacologically active and act at the same sites as drugs.",
 quote:"Um, sometimes we've even looked at herbal products and found prescription medications in with the herbal products.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Drug-Herbal Interactions' (p. 23); (T) 10/28 transcript"},

{id:"L22-081", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-herb-food", skill:"recall",
 concept:"food-competes-enzyme", tags:["smith"], source:"both",
 stem:"A food component competes with a drug for its metabolizing enzymes. How does it act, and which foods are the example?",
 options:[
  {t:"As an inhibitor; citrus fruits", correct:true, why:"A competitor for the enzymes is an inhibitor; she named the compounds in citrus fruits."},
  {t:"As an inducer; charbroiled meat", correct:false, why:"Charbroiled foods induce CYP1A2; they do not compete for the enzyme."},
  {t:"As an adsorbent; spinach and broccoli", correct:false, why:"Spinach and broccoli are the vitamin K example, a pharmacodynamic antagonism of warfarin."},
  {t:"As a chelator; dairy calcium", correct:false, why:"Calcium complexes quinolones in the gut; it does not act on enzymes."}],
 teach:"Food may affect a drug's metabolizing enzymes. A food that competes for the enzymes acts as an inhibitor; a food may also induce them. The compounds in citrus fruits are the competing foods.",
 quote:"Other issues are, uh, you get some food products that will compete with metabolizing enzymes. That's the issue for a lot of those, um, compounds in those citric, uh, citrus fruits that we mentioned.",
 note:"Conflict: while going over Table 18-3 Dr. Smith said the citrus fruits \"will induce\" the CYP3A family and that the non-drug examples \"all just happen to be inducers\" (the printed table places grapefruit, Seville and bitter oranges and garlic under its Inducer heading). Here, on food-drug interactions, she said they compete with metabolizing enzymes, and p. 27 says a competing food is an inhibitor. Keyed to this later statement and p. 27.",
 cite:"DDI Lecture Students 2026 (1).pdf slides 'Food-Drug Interactions' (p. 27) and 'Pharmacokinetic Interactions Drug Elimination and Clearance' (p. 15, Table 18-3); (T) 10/28 transcript"},

{id:"L22-082", lecture:"L22", prof:"Smith", tier:"new", lowYield:true, topic:"L22", sub:"ddi-herb-food", skill:"apply",
 concept:"st-johns-wort-pgp", tags:["smith"], source:"both",
 stem:"St. John's wort also acts on intestinal P-glycoprotein (P-gp). What happens to a patient's digoxin levels?",
 options:[
  {t:"Lower digoxin levels", correct:true, why:"The St. John's wort table lists increased P-gp-catalyzed efflux and lower levels of digoxin."},
  {t:"Higher digoxin levels", correct:false, why:"More efflux by P-gp means less digoxin absorbed."},
  {t:"No change in digoxin", correct:false, why:"Digoxin is listed as an object drug of this interaction."},
  {t:"Digoxin displaced from muscle", correct:false, why:"Displacement from muscle is the quinidine example."}],
 teach:"St. John's wort induces CYP3A4 (lowering protease inhibitors, benzodiazepines, calcium channel blockers and cyclosporine), induces CYP2C9 and CYP1A2 (lowering warfarin), and increases intestinal P-gp efflux, which pumps drug back into the gut and lowers digoxin. It also adds serotonin effects with SSRIs and MAOIs.",
 quote:"We didn't talk about the fact that it is a substrate for P glycoprotein. It'll mess up other drugs' bioavailability, OK?",
 note:"Dr. Smith called St. John's wort a substrate for P-glycoprotein; the table lists it as increasing P-gp-catalyzed efflux of substrate drugs. Keyed to the table's effect on digoxin, which matches her point that it changes other drugs' bioavailability. The digoxin row was on screen but not discussed; marked lowYield.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Drug-Herbal Interactions' (p. 24, Table 18-6); (T) 10/28 transcript"},

{id:"L22-083", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-herb-food", skill:"apply", multi:true,
 concept:"warfarin-vitk-products", tags:["smith"], source:"both",
 stem:"A patient on warfarin uses several products. Which may result in inadequate anticoagulation? Select all that apply.",
 options:[
  {t:"Coenzyme Q10", correct:true, why:"Its chemical structure is similar to vitamin K."},
  {t:"Wheat grass", correct:true, why:"It contains high levels of vitamin K."},
  {t:"Spinach and broccoli", correct:true, why:"They contain vitamin K, which antagonizes warfarin."},
  {t:"Ginger", correct:false, why:"Ginger inhibits platelets, raising bleeding risk rather than reducing the anticoagulation."},
  {t:"Feverfew supplements", correct:false, why:"Feverfew inhibits platelets and adds to the bleeding risk."},
  {t:"Garlic", correct:false, why:"Garlic inhibits platelets, raising bleeding risk rather than reducing anticoagulation."}],
 teach:"Warfarin has a narrow therapeutic index, and vitamin K is its antidote. Coenzyme Q10 is structurally similar to vitamin K, and wheat grass, spinach and broccoli contain vitamin K; each can antagonize warfarin and leave anticoagulation inadequate.",
 quote:"Um, a lot of our herbal products have vitamin K in them or act like vitamin K, like coenzyme Q10, so it's similar to vitamin K.",
 cite:"DDI Lecture Students 2026 (1).pdf slides 'Drug-Herbal Interactions' (p. 25) and 'Food-Drug Interactions' (p. 27); (T) 10/28 transcript"},

{id:"L22-084", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-herb-food", skill:"apply",
 concept:"garlic-ginger-feverfew-bleeding", tags:["smith"], source:"both",
 stem:"A patient on warfarin takes garlic, ginger and feverfew. What is the risk, and how does it arise?",
 options:[
  {t:"More bleeding; they inhibit platelets", correct:true, why:"These herbs directly inhibit platelets, a different mechanism from warfarin."},
  {t:"Clotting; they supply vitamin K", correct:false, why:"The vitamin K products are coenzyme Q10, wheat grass, spinach and broccoli."},
  {t:"More bleeding; they chelate vitamin K", correct:false, why:"The herbs act on platelets, not by binding vitamin K."},
  {t:"No risk; herbs lack activity", correct:false, why:"Herbs have pharmacologic activity; these three are antiplatelet."}],
 teach:"Garlic, ginger and feverfew directly inhibit platelets. With warfarin this adds anticoagulation from a different angle, so bleeding risk rises. Narrow therapeutic index drugs are at greater risk.",
 quote:"Other products like garlic, ginger, feverfew, they are also antiplatelet by a different mechanism, so you could be overcoagulating your patients from a different angle when you're using these herbal products, OK?",
 note:"The caption says \"overcoagulating\"; from context and p. 25 (\"increase risk for bleeding with warfarin\") Dr. Smith meant over-anticoagulating.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Drug-Herbal Interactions' (p. 25); (T) 10/28 transcript"},

{id:"L22-085", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-herb-food", skill:"recall",
 concept:"smoking-cyp1a2-objects", tags:["smith"], source:"both",
 stem:"Besides theophylline, which object drugs are listed for the smoking interaction?",
 options:[
  {t:"Diazepam and tricyclic antidepressants", correct:true, why:"Both are metabolized by the CYP1A enzymes that smoke induces."},
  {t:"Tacrolimus and other calcineurin inhibitors", correct:false, why:"Tacrolimus is the phenytoin and CYP3A induction example."},
  {t:"Atorvastatin and other statins", correct:false, why:"Atorvastatin is the cimetidine inhibition example."},
  {t:"Lithium and digoxin", correct:false, why:"These are the diuretic pharmacodynamic examples."}],
 teach:"Smoking and ethanol are the most common chemical-drug interactions. The polycyclic aromatic hydrocarbons in smoke induce CYP1A2 (and CYP1A1), which lowers the levels of theophylline, diazepam and tricyclic antidepressants.",
 quote:"it'll affect theophylline like we already talked about, but also diazepam and your tricyclic antidepressants are metabolized by that category of enzymes, so smoking will increase their clearance.",
 note:"P. 29 names CYP1A2 only (and prints \"CYPA2\" once); Dr. Smith added CYP1A1 by hand on the screen.",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Chemical-Drug Interactions' (p. 29); (T) 10/28 transcript"},

{id:"L22-086", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-herb-food", skill:"apply", dupOf:"L13-020",
 concept:"ethanol-induction-acetaminophen", tags:["smith"], source:"both",
 stem:"A patient who drinks ethanol regularly takes acetaminophen. Which ethanol effect raises the possibility of liver toxicity?",
 options:[
  {t:"Induction of CYP2E1 and CYP3A", correct:true, why:"More of these enzymes means more of the dose is bioactivated."},
  {t:"Inhibition of CYP2E1 and CYP3A", correct:false, why:"Inhibition would make less of the toxic metabolite."},
  {t:"Induction of CYP1A2 alone", correct:false, why:"Ethanol does induce CYP1A2, but that lowers clozapine, cyclobenzaprine, imipramine and naproxen."},
  {t:"Displacement of acetaminophen from albumin", correct:false, why:"The listed mechanism is enzyme induction."}],
 teach:"Ethanol can raise or lower hepatic drug-metabolizing enzyme activity. It induces CYP2E1 and CYP3A, so more of an acetaminophen dose is bioactivated to the toxic metabolite, raising the chance of hepatotoxicity. It also induces CYP1A2, which lowers clozapine, imipramine and naproxen.",
 quote:"Um, and the risk for, uh, overdosing with acetaminophen, but ethanol can also induce some of these other enzymes like 1A2 as well, and I'm pointing that out on the slide",
 cite:"DDI Lecture Students 2026 (1).pdf slide 'Chemical-Drug Interactions' (p. 30); (T) 10/28 transcript"},
{id:"L22-087", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"naranjo", skill:"tell", readingId:"naranjo",
 concept:"naranjo-lowest-ranking", tags:["smith"], source:"both",
 stem:"The Naranjo algorithm page labels a total score of 0 'doubtful'. In the ranking definite, probable, possible, remote, which names the same lowest category?",
 options:[
  {t:"Remote", correct:true, why:"Remote is her lowest ranking; the algorithm page calls the same band doubtful."},
  {t:"Possible", correct:false, why:"Possible is a score of 1 to 4: the drug appears to be associated."},
  {t:"Probable", correct:false, why:"Probable is a score of 5 to 8: the drug is the apparent cause."},
  {t:"None; doubtful is a fifth ranking", correct:false, why:"Doubtful and remote are two names for one lowest category."}],
 teach:"Her Naranjo rankings are definite, probable, possible and remote. The page prints the bands as 9 definite, 5 to 8 probable, 1 to 4 possible and 0 doubtful. Remote and doubtful name the same lowest category.",
 note:"Conflict: the slide (p. 21) and her words say 'remote'; the Naranjo page says '0=doubtful'. Keyed to her list, with the page's term in the stem.",
 quote:"So these are the rankings definite, probable, possible, or remote.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Causality of Adverse Drug Reactions' (p. 21); Naranjo Algorithm (one page); transcript 10/28"},

/* ---------------- Exam 4 study list item 5: using the Naranjo algorithm (full ten-question cases) ---------------- */
{id:"L22-088", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"naranjo", skill:"calc", readingId:"naranjo", core:true, coreWhy:"her Exam 4 study list item 5 (Naranjo)",
 concept:"naranjo-case-definite", tags:["smith"], source:"both",
 stem:"Naranjo scoring, all ten questions: previous conclusive reports exist (Q1 yes); the reaction appeared after the drug was given (Q2 yes); it improved when the drug was stopped (Q3 yes); it reappeared when the drug was given again (Q4 yes); no other cause or drug could on its own explain it (Q5 no); no placebo was given (Q6 do not know); no drug level was measured (Q7 do not know); the dose was never changed (Q8 no); the patient never had a similar reaction before (Q9 no); a lab test confirmed the reaction (Q10 yes). What is the total and its category?",
 options:[
  {t:"9; definite", correct:true, why:"+1 +2 +1 +2 +2 +0 +0 +0 +0 +1 = 9, the page's definite band."},
  {t:"8; probable", correct:false, why:"Leaves out the +1 for objective evidence (Q10 yes)."},
  {t:"7; probable", correct:false, why:"Scores Q5 no as 0; with no alternative cause, a no on Q5 earns +2."},
  {t:"10; definite", correct:false, why:"Scores Q6 as +1; no placebo was given, so Q6 is do not know, worth 0."}],
 teach:"Score each answer from its own row: Q1 yes +1; Q2 yes +2; Q3 yes +1; Q4 yes +2; Q5 no +2 (a reversed row, where no means no other cause); Q6 do not know 0; Q7 do not know 0; Q8 no 0; Q9 no 0; Q10 yes +1. Total 1+2+1+2+2+0+0+0+0+1 = 9, which the page prints as definite: the drug is likely the true cause. The two timing questions worth +2 (Q2 and Q4) and the reversed Q5 carry most of the total.",
 quote:"So make sure that you are scoring the responses appropriately with this algorithm",
 cite:"Naranjo Algorithm (one page), questions 1-10 and total score; ADE-Lecture-Students-2026.pdf slide 'Causality of Adverse Drug Reactions' (p. 21); transcript 10/28"},

{id:"L22-089", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"naranjo", skill:"calc", readingId:"naranjo", core:true, coreWhy:"her Exam 4 study list item 5 (Naranjo)",
 concept:"naranjo-case-doubtful", tags:["smith"], source:"both",
 stem:"Naranjo scoring, all ten questions: no previous reports (Q1 no); the reaction appeared after the drug was given (Q2 yes); it did not improve when the drug was stopped (Q3 no); it did not reappear when the drug was given again (Q4 no); another drug could on its own explain it (Q5 yes); it reappeared when a placebo was given (Q6 yes); no drug level was measured (Q7 do not know); the dose was never changed (Q8 no); the patient had a similar reaction to a similar drug before (Q9 yes); no objective evidence (Q10 no). What is the total and its category?",
 options:[
  {t:"0; doubtful (remote)", correct:true, why:"0 + 2 + 0 - 1 - 1 - 1 + 0 + 0 + 1 + 0 = 0: doubtful on the page, remote in the ranking."},
  {t:"-1; doubtful (remote)", correct:false, why:"Leaves out the +1 for a similar reaction on previous exposure (Q9 yes)."},
  {t:"3; possible", correct:false, why:"Scores Q5 yes as +2; Q5 is reversed, so another possible cause is -1."},
  {t:"1; possible", correct:false, why:"Scores Q4 no as 0; a no on Q4 (re-given, no reaction) is -1."}],
 teach:"Score each answer from its own row: Q1 no 0; Q2 yes +2; Q3 no 0; Q4 no -1; Q5 yes -1; Q6 yes -1; Q7 do not know 0; Q8 no 0; Q9 yes +1; Q10 no 0. Total 0+2+0-1-1-1+0+0+1+0 = 0. The page labels 0 doubtful; her ranking calls the lowest category remote: the drug is not likely responsible. Three -1 answers cancel the +2 for timing and the +1 for a previous reaction.",
 quote:"So these are the rankings definite, probable, possible, or remote.",
 note:"The page prints \"0=doubtful\"; the slide and her words say remote. The page prints no band for totals below 0.",
 cite:"Naranjo Algorithm (one page), questions 1-10 and total score; ADE-Lecture-Students-2026.pdf slide 'Causality of Adverse Drug Reactions' (p. 21); transcript 10/28"},

{id:"L22-090", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"naranjo", skill:"recall", readingId:"naranjo", multi:true, core:true, coreWhy:"her Exam 4 study list item 5 (Naranjo); she said some answers are negative",
 concept:"naranjo-negative-answers", tags:["smith"], source:"both",
 stem:"Which Naranjo answers subtract a point from the total? Select all that apply.",
 options:[
  {t:"Q2 no: the event did not follow the drug", correct:true, why:"Q2 scores +2 for yes, -1 for no."},
  {t:"Q4 no: it did not return when the drug was re-given", correct:true, why:"Q4 scores +2 for yes, -1 for no."},
  {t:"Q5 yes: another cause could explain it", correct:true, why:"Q5 is reversed: -1 for yes, +2 for no."},
  {t:"Q6 yes: it reappeared with a placebo", correct:true, why:"Q6 scores -1 for yes, +1 for no."},
  {t:"Q6 no: it did not reappear with a placebo", correct:false, why:"A no on Q6 adds a point (+1)."},
  {t:"Q3 no: it did not improve when the drug was stopped", correct:false, why:"Q3 scores +1 for yes and 0 for no."},
  {t:"Q7 do not know: no drug level was measured", correct:false, why:"Do not know is 0 on every question."}],
 teach:"Four answers on the Naranjo page score -1: Q2 no, Q4 no, Q5 yes and Q6 yes. Each points away from the drug: the reaction did not follow it, did not return with it, has another explanation, or came back with a placebo. Q6 no is +1, Q5 no is +2, and do not know is always 0.",
 quote:"sometimes a no is negative",
 cite:"Naranjo Algorithm (one page), questions 1-10; ADE-Lecture-Students-2026.pdf slide 'Causality of Adverse Drug Reactions' (p. 21); transcript 10/28"},

{id:"L22-091", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"naranjo", skill:"recall", readingId:"naranjo", multi:true, core:true, coreWhy:"her Exam 4 study list item 5 (Naranjo)",
 concept:"naranjo-plus-one-answers", tags:["smith"], source:"both",
 stem:"Which Naranjo answers add exactly one point? Select all that apply.",
 options:[
  {t:"Q7 yes: toxic drug level detected", correct:true, why:"Q7 to Q10 score +1 for yes, 0 for no or do not know."},
  {t:"Q8 yes: worse at a higher dose or better at a lower one", correct:true, why:"Dose-response, +1 for yes."},
  {t:"Q9 yes: a similar reaction on previous exposure", correct:true, why:"+1 for yes."},
  {t:"Q10 yes: confirmed by objective evidence", correct:true, why:"+1 for yes."},
  {t:"Q6 no: no reaction with a placebo", correct:true, why:"Q6 scores +1 for no (and -1 for yes)."},
  {t:"Q2 yes: the event followed the drug", correct:false, why:"Q2 yes is +2."},
  {t:"Q5 no: no other cause could explain it", correct:false, why:"Q5 no is +2."}],
 teach:"The +1 answers are Q1 yes, Q3 yes, Q6 no and Q7 to Q10 yes. The +2 answers are Q2 yes, Q4 yes and Q5 no. Questions 7 to 10 (toxic level, dose-response, previous similar reaction, objective evidence) never subtract: no and do not know are both 0.",
 quote:"sometimes a yes is 2 points, sometimes it's 1 point, sometimes a no is negative.",
 cite:"Naranjo Algorithm (one page), questions 1-10; ADE-Lecture-Students-2026.pdf slide 'Causality of Adverse Drug Reactions' (p. 21); transcript 10/28"},
/* ---------------- Exam 4 study list item 1 gap fill: cutaneous reactions (pp. 29-34, on the objectives, skipped in class) ---------------- */
{id:"L22-092", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"hypersens", skill:"apply", lowYield:true,
 concept:"urticaria-no-rechallenge", tags:["smith"], source:"slide",
 stem:"A patient develops drug-induced urticaria (hives), which is IgE mediated. What follows for re-challenge with the drug?",
 options:[
  {t:"Do not re-challenge the patient with the drug", correct:true, why:"Urticaria is IgE mediated, so the patient is not re-challenged."},
  {t:"Re-challenge at a lower dose to confirm the cause", correct:false, why:"An IgE-mediated reaction can recur on re-exposure, at any dose."},
  {t:"Re-challenge after a course of antihistamines", correct:false, why:"Antihistamines (often with oral corticosteroids) treat the hives; they do not make re-challenge safe."},
  {t:"Re-challenge freely; urticaria is non-immunologic", correct:false, why:"Urticaria is IgE mediated, an immunologic (type I) reaction."}],
 teach:"Drug-induced urticaria is patchy, flat, red and spreading, starts on the trunk, and appears within hours or days of the offending agent. It often needs oral corticosteroids and antihistamines. It is IgE mediated and can recur on re-exposure, so the patient is not re-challenged.",
 quote:"That's hives. Has anybody ever had hives? That's the worst.",
 note:"lowYield: on 10/28 she showed only the hives and Stevens-Johnson images from this section and said she would not cover the skin, liver and renal slides. The slide title is printed 'Uticaria'.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Uticaria' (p. 32); transcript 10/28"},

{id:"L22-093", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"hypersens", skill:"tell", lowYield:true,
 concept:"phototoxic-vs-photoallergic", tags:["smith"], source:"slide",
 stem:"Photosensitivity drug reactions look like sunburn. How does phototoxicity differ from a photoallergic reaction?",
 options:[
  {t:"Phototoxicity is non-immunologic; photoallergy is immunologic and rare", correct:true, why:"Phototoxicity needs no immune response; photoallergy is an immune reaction and rare."},
  {t:"Phototoxicity is immunologic; photoallergy is non-immunologic", correct:false, why:"Reversed."},
  {t:"Both are IgE mediated and need a re-challenge to confirm", correct:false, why:"Phototoxicity is non-immunologic; IgE mediation and no re-challenge describe urticaria."},
  {t:"Phototoxicity is the rare one; photoallergy is the common non-immune kind", correct:false, why:"The photoallergic reaction is the immunologic and rare one."}],
 teach:"Photosensitivity reactions look like sunburn. Phototoxicity is non-immunologic; a photoallergic reaction is immunologic and rare. Both get topical corticosteroids and antihistamines, often oral steroids, and sunscreen. Common causes: fluoroquinolones, NSAIDs, sulfonamides, thiazides and TCAs.",
 quote:"I'm not gonna cover all the slides that I had for like skin reactions",
 note:"lowYield: slide text she did not cover (10/28); the quote is her statement that she skipped the section.",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Photosensitivity Drug Reactions' (p. 34); transcript 10/28"},
{id:"L22-094", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ade-types", skill:"apply", core:true, coreWhy:"her Exam 4 study list item 1 (objectives): the five ADE types",
 concept:"adwe-apply", tags:["smith"], source:"both",
 stem:"A patient on long-term paroxetine stops it abruptly and develops dizziness and flu-like symptoms. Which type of adverse drug event is this?",
 options:[
  {t:"Adverse drug withdrawal event", correct:true, why:"Stopping a long-term drug too quickly produces withdrawal symptoms; she named SSRIs as a class to counsel."},
  {t:"Therapeutic failure", correct:false, why:"The drug was not failing to work at a suboptimal dose; it was stopped."},
  {t:"Adverse drug reaction at a normal dose", correct:false, why:"An ADR is a noxious effect of the drug at a normal dose, not a withdrawal effect from stopping it."},
  {t:"Medication error", correct:false, why:"No process mistake in prescribing, dispensing or giving the drug is described."}],
 teach:"Stopping a long-term drug too quickly gives an adverse drug withdrawal event. She accepted SSRIs such as paroxetine as a class to counsel patients about before stopping.",
 quote:"you can definitely get withdrawal symptoms",
 cite:"ADE-Lecture-Students-2026.pdf slides 'Types of ADEs' (p. 6), 'Adverse Drug Withdrawal Events' (p. 8); transcript 10/28"},
{id:"L22-095", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ade-types", skill:"apply", core:true, coreWhy:"her Exam 4 study list item 1 (objectives): the medication misadventures relationships of ADE, ADR and medication error",
 concept:"venn-error-ade-apply", tags:["smith"], source:"both",
 stem:"A nurse gives ten times the ordered dose of morphine and the patient stops breathing. Which terms apply?",
 options:[
  {t:"A medication error that is also an adverse drug event", correct:true, why:"A preventable mistake in the medication process is a medication error, and the injury makes it an adverse drug event."},
  {t:"An adverse drug reaction from the resulting harm", correct:false, why:"An ADR is a noxious effect at a normal dose; a tenfold overdose is not an ADR."},
  {t:"A medication error, but not an adverse drug event in this case", correct:false, why:"The patient was injured, so it is also an adverse drug event."},
  {t:"A therapeutic failure", correct:false, why:"The drug was given in excess and harmed the patient; it did not fail to work."}],
 teach:"A preventable mistake in the medication process is a medication error; because the patient was injured, it is also an adverse drug event. It is not an adverse drug reaction, which is a noxious effect at a normal dose, not an overdose.",
 quote:"it's not an overdose causing symptoms",
 cite:"ADE-Lecture-Students-2026.pdf slides 'Medication Misadventures' (p. 4), 'Adverse Drug Events (ADE) definition' (p. 5), 'Medication Errors (MEs)' (p. 10), 'Adverse Drug Reaction (ADR)' (p. 12); transcript 10/28"},
{id:"L22-096", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"med-errors", skill:"apply", core:true, coreWhy:"her Exam 4 study list: the reporting routes, MedWatch versus ISMP MERP",
 concept:"reporting-routes-apply", tags:["smith"], source:"both",
 stem:"Two events in one week: a rash at a normal dose of a newly marketed antibiotic, and a look-alike vial nearly given to the wrong patient. Where is each reported?",
 options:[
  {t:"Rash: MedWatch; near-miss: ISMP MERP", correct:true, why:"An ADR at a normal dose goes to MedWatch; a medication error, even a near miss, goes to the ISMP Medication Errors Reporting Program."},
  {t:"Rash: ISMP MERP; near-miss: MedWatch", correct:false, why:"Reversed: the ADR goes to MedWatch and the error to ISMP MERP."},
  {t:"Both: MedWatch", correct:false, why:"MedWatch takes the ADR; the medication error goes to ISMP MERP."},
  {t:"Rash: MedWatch; near-miss: nowhere, with no harm done", correct:false, why:"A near miss is still reported to ISMP MERP; no harm does not excuse it."}],
 teach:"An adverse drug reaction at a normal dose is reported to MedWatch. A medication error, including a near miss that is caught, is reported to the ISMP Medication Errors Reporting Program.",
 quote:"medication error about to, about to happen",
 cite:"ADE-Lecture-Students-2026.pdf slides 'Reporting Medication Errors' (p. 11), 'Adverse Drug Reaction (ADR)' (p. 12); transcript 10/28"},
{id:"L22-097", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"ddi-pd", skill:"apply", core:true, coreWhy:"her Exam 4 study list item 1 (objectives): precipitant versus object and pharmacokinetic versus pharmacodynamic interactions",
 concept:"digoxin-diuretic-pd-apply", tags:["smith"], source:"both",
 stem:"A patient stable on digoxin is started on a potassium-wasting diuretic; the potassium falls and the heart rate drops. Name the precipitant drug and the kind of interaction.",
 options:[
  {t:"The diuretic; pharmacodynamic (greater sensitivity to digoxin)", correct:true, why:"The added drug is the precipitant; low potassium increases sensitivity to digoxin, a pharmacodynamic effect."},
  {t:"Digoxin; pharmacodynamic (greater sensitivity to the diuretic)", correct:false, why:"Digoxin is the object drug already on board; the diuretic is the precipitant."},
  {t:"The diuretic; pharmacokinetic (displacement from muscle)", correct:false, why:"Nothing is displaced; the interaction is a change in sensitivity, not in handling."},
  {t:"The diuretic; pharmaceutical (incompatibility)", correct:false, why:"No mixing incompatibility is involved; the effect is in the patient."}],
 teach:"The drug added to the stable regimen is the precipitant; digoxin is the object drug. Low potassium increases the block of the sodium-potassium ATPase, so the patient is more sensitive to digoxin: a pharmacodynamic interaction.",
 quote:"the precipitant drug is causing sensitivity to the object",
 cite:"DDI Lecture Students 2026 (1).pdf slides 'Drug Interactions Introduction' (pp. 5, 7), 'Pharmacodynamic Interactions Examples' (p. 20); (T) 10/28 transcript"},
{id:"L22-098", lecture:"L22", prof:"Smith", tier:"new", topic:"L22", sub:"immuno-nonimmuno", skill:"apply", core:true, coreWhy:"her Exam 4 study list item 1 (objectives): the nonimmunologic reaction types, including pseudoallergic",
 concept:"pseudoallergic-apply", tags:["smith"], source:"both",
 stem:"Minutes after a radiocontrast dye injection a patient itches and flushes; later testing finds no IgE antibody to the dye. Which classification fits?",
 options:[
  {t:"Nonimmunologic, unpredictable: pseudoallergic", correct:true, why:"It looks allergic but the drug itself causes it, with no immune mechanism: a pseudoallergic reaction."},
  {t:"Immunologic: type I hypersensitivity", correct:false, why:"No IgE antibody was found, so it is not an immune type I reaction."},
  {t:"Nonimmunologic, predictable: pharmacologic side effect", correct:false, why:"A pharmacologic side effect is predictable; this itch mimics allergy and is unpredictable."},
  {t:"Nonimmunologic, unpredictable: intolerance", correct:false, why:"Intolerance is the aspirin-tinnitus example, not the radiocontrast itch."}],
 teach:"A reaction that looks allergic but has no immune mechanism, caused by the drug itself, is pseudoallergic, one of the unpredictable nonimmunologic reactions. The radiocontrast itch is her example.",
 quote:"It's not, it's just the drug doing it",
 cite:"ADE-Lecture-Students-2026.pdf slide 'Immunologic reactions' (p. 23); transcript 10/28"}
);
